import type {AiLevel} from '../journey';

export const pjAdmin:AiLevel={id:'pj-admin',title:'管理后台和权限',summary:'用户分角色，只有管理员能增删改题目：401 和 403 的区别、数据库迁移加列、管理接口的校验和审计日志',lessons:[
  {title:'这一关做什么：管理后台和权限',body:'到现在为止，加题只能改 data/questions.json 再重新导入。这一关做一个管理后台，让管理员在网页上管理题库：\n一、新增题目：POST /api/admin/questions；\n二、修改题目：PUT /api/admin/questions/{id}；\n三、删除题目：DELETE /api/admin/questions/{id}；\n四、只有管理员能用：没登录 401，登录了但不是管理员 403。\n用户分成两种“角色”（role）：普通用户 user 和管理员 admin，存在 users 表新加的 role 列里。谁是管理员，由环境变量 ADMIN_USERNAMES 指定（多个用逗号隔开）：这些用户名注册时自动成为管理员，服务启动时也会把已经注册的这些账号设成管理员。'},
  {title:'认证和授权：401 和 403 的区别',body:'这两个词很像，意思不同：\n认证（Authentication）：确认“你是谁”。第 9 关的登录就是认证，没有通过认证返回 401 Unauthorized（名字有点误导，其实是“未认证”）；\n授权（Authorization）：确认“你能做什么”。已经知道你是谁了，但你没有这个权限，返回 403 Forbidden。\n所以管理接口的检查顺序是：先认人（没登录 401），再看角色（不是管理员 403），都通过了才执行。\n这种“按角色决定能做什么”的做法叫 RBAC（基于角色的访问控制）。我们只有两种角色，规则写成一个“要求管理员”的函数或中间件，所有管理接口都先经过它。以后角色多了（比如“编辑”只能改题不能删题），也只需要改这一处的规则。'},
  {title:'给已有的表加一列：数据库迁移',body:'users 表在第 9 关就建好了，学员的数据库里已经有数据。现在要加一列 role，不能删表重建，要用：\nALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'\n已有的每一行都会得到默认值 user。\n问题是这条语句只能执行一次：第二次启动再执行，会因为“列已经存在”报错。CREATE TABLE 有 IF NOT EXISTS，但 SQLite 的 ADD COLUMN 没有。所以先查一下这一列在不在：SQLite 的 PRAGMA table_info(users) 会返回表的每一列，没有 role 才执行 ALTER。\n这种“随着代码升级，修改数据库结构”的操作叫数据库迁移（migration）。项目大了以后，一般用专门的工具管理：每次修改写成一个编号的迁移文件，数据库里记下执行到了第几个，启动时自动执行还没执行的。Go 常用 golang-migrate，Java 常用 Flyway，Node.js 有 Knex，Python 有 Alembic。'},
  {title:'管理接口也要严格校验',body:'管理员也会手滑，也可能账号被盗，所以管理接口的输入照样要检查：\n科目：1 到 20 个小写字母、数字或横线；\n题目：1 到 200 个字；\n参考答案：1 到 2000 个字；\n难度：1、2、3 之一。\n不合格返回 400。修改和删除不存在的题目返回 404。\n还有两个上线前一定要想到的问题：\n一、XSS：题目内容现在来自别人的输入了。第 5 关一直强调“数据当文本显示”，现在终于用上了：管理员写的 <script> 在页面上只会原样显示出来；\n二、审计：谁在什么时候改了什么，最好记一条日志。我们先在日志里打印一行“管理员 xxx 删除了第 n 题”，正式的系统会有专门的审计日志表。'},
  {title:'管理接口的约定',body:'三个接口都要求登录（否则 401）并且是管理员（否则 403）。新增和修改的请求正文一样。',code:`POST /api/admin/questions
{"category": "go", "title": "题目", "answer": "参考答案", "difficulty": 2}
→ 201 {"id": 25, "category": "go", "title": "题目", "answer": "参考答案", "difficulty": 2}
→ 400 不合格的题目

PUT /api/admin/questions/{id}（正文同上）
→ 200 修改后的题目 / 404 题目不存在

DELETE /api/admin/questions/{id}
→ 204 没有正文 / 404 题目不存在`,explain:[{at:'POST /api/admin/questions',to:'→ 400 不合格的题目',text:'新增：不用传编号，数据库自动生成，返回带编号的新题目。'},{at:'PUT /api/admin/questions/{id}',to:'→ 200 修改后的题目',text:'修改：编号在地址里，正文是完整的新内容。'},{at:'DELETE /api/admin/questions/{id}',to:'→ 204 没有正文',text:'删除：成功返回 204 No Content，表示成功了但没有内容要返回。'}]},
  {title:'任务一：角色列和题目的增删改',body:'数据访问层：迁移 role 列（已经给出），新增题目（已经给出）；你来写修改和删除，并且能告诉上层“这道题存不存在”。',variants:{go:{practice:{steps:['新建 internal/store/admin.go，读懂已经给出的部分，补完 TODO。','go build ./... 确认能编译。'],expect:'go build ./... 没有输出'},code:'// internal/store/admin.go\npackage store\n\n// MigrateRoles 给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员。\nfunc (s *UserStore) MigrateRoles(admins []string) error {\n    var n int\n    if err := s.db.QueryRow("SELECT COUNT(*) FROM pragma_table_info(\'users\') WHERE name = \'role\'").Scan(&n); err != nil {\n        return err\n    }\n    if n == 0 {\n        if _, err := s.db.Exec("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'"); err != nil {\n            return err\n        }\n    }\n    for _, name := range admins {\n        if _, err := s.db.Exec("UPDATE users SET role = \'admin\' WHERE username = ?", name); err != nil {\n            return err\n        }\n    }\n    return nil\n}\n\nfunc (s *UserStore) Role(userID int) (string, error) {\n    var role string\n    err := s.db.QueryRow("SELECT role FROM users WHERE id = ?", userID).Scan(&role)\n    return role, err\n}\n\nfunc (s *UserStore) SetRole(userID int, role string) error {\n    _, err := s.db.Exec("UPDATE users SET role = ? WHERE id = ?", role, userID)\n    return err\n}\n\n// CreateQuestion 新增一道题，编号由数据库自动生成。\nfunc (s *QuestionStore) CreateQuestion(q Question) (Question, error) {\n    res, err := s.db.Exec("INSERT INTO questions (category, title, answer, difficulty) VALUES (?, ?, ?, ?)",\n        q.Category, q.Title, q.Answer, q.Difficulty)\n    if err != nil {\n        return q, err\n    }\n    id, err := res.LastInsertId()\n    q.ID = int(id)\n    return q, err\n}\n\n// UpdateQuestion 修改一道题，不存在时返回 ErrNotFound。\nfunc (s *QuestionStore) UpdateQuestion(q Question) error {\n    // TODO 1：UPDATE questions SET category = ?, title = ?, answer = ?, difficulty = ? WHERE id = ?；\n    //         用 RowsAffected 看改了几行，0 行说明题目不存在，返回 ErrNotFound\n    return nil\n}\n\n// DeleteQuestion 删除一道题，不存在时返回 ErrNotFound。\nfunc (s *QuestionStore) DeleteQuestion(id int) error {\n    // TODO 2：DELETE FROM questions WHERE id = ?，同样用 RowsAffected 判断是否存在\n    return nil\n}',explain:[{at:'// internal/store/admin.go',to:'package store',text:'管理后台用到的数据访问，作为 UserStore 和 QuestionStore 的新方法，放在一个新文件里。'},{at:'func (s *UserStore) MigrateRoles(admins []string) error {',to:'return err',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行，用 WHERE name = \'role\' 看这一列存不存在。'},{at:'if n == 0 {',to:'return err',text:'没有才加：ALTER TABLE … ADD COLUMN 给已有的表加一列，已有的每一行都得到默认值 user。'},{at:'for _, name := range admins {',to:'return nil',text:'把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'func (s *UserStore) Role(',to:'return role, err',text:'查一个用户的角色。'},{at:'func (s *UserStore) SetRole(',to:'return err',text:'修改一个用户的角色。'},{at:'func (s *QuestionStore) CreateQuestion(',to:'return q, err',text:'新增题目：插入时不写 id，INTEGER PRIMARY KEY 会自动生成一个比现有最大值大的编号。'},{at:'id, err := res.LastInsertId()',to:'return q, err',text:'用 LastInsertId 取回自动生成的编号，放进返回的题目里。'},{at:'func (s *QuestionStore) UpdateQuestion(',to:'return nil',text:'修改题目，要你补全。'},{at:'func (s *QuestionStore) DeleteQuestion(',to:'return nil',text:'删除题目，要你补全。'}],solution:{code:'// internal/store/admin.go\npackage store\n\n// MigrateRoles 给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员。\nfunc (s *UserStore) MigrateRoles(admins []string) error {\n    var n int\n    if err := s.db.QueryRow("SELECT COUNT(*) FROM pragma_table_info(\'users\') WHERE name = \'role\'").Scan(&n); err != nil {\n        return err\n    }\n    if n == 0 {\n        if _, err := s.db.Exec("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'"); err != nil {\n            return err\n        }\n    }\n    for _, name := range admins {\n        if _, err := s.db.Exec("UPDATE users SET role = \'admin\' WHERE username = ?", name); err != nil {\n            return err\n        }\n    }\n    return nil\n}\n\nfunc (s *UserStore) Role(userID int) (string, error) {\n    var role string\n    err := s.db.QueryRow("SELECT role FROM users WHERE id = ?", userID).Scan(&role)\n    return role, err\n}\n\nfunc (s *UserStore) SetRole(userID int, role string) error {\n    _, err := s.db.Exec("UPDATE users SET role = ? WHERE id = ?", role, userID)\n    return err\n}\n\n// CreateQuestion 新增一道题，编号由数据库自动生成。\nfunc (s *QuestionStore) CreateQuestion(q Question) (Question, error) {\n    res, err := s.db.Exec("INSERT INTO questions (category, title, answer, difficulty) VALUES (?, ?, ?, ?)",\n        q.Category, q.Title, q.Answer, q.Difficulty)\n    if err != nil {\n        return q, err\n    }\n    id, err := res.LastInsertId()\n    q.ID = int(id)\n    return q, err\n}\n\n// UpdateQuestion 修改一道题，不存在时返回 ErrNotFound。\nfunc (s *QuestionStore) UpdateQuestion(q Question) error {\n    res, err := s.db.Exec("UPDATE questions SET category = ?, title = ?, answer = ?, difficulty = ? WHERE id = ?",\n        q.Category, q.Title, q.Answer, q.Difficulty, q.ID)\n    if err != nil {\n        return err\n    }\n    if n, err := res.RowsAffected(); err != nil || n == 0 {\n        return ErrNotFound\n    }\n    return nil\n}\n\n// DeleteQuestion 删除一道题，不存在时返回 ErrNotFound。\nfunc (s *QuestionStore) DeleteQuestion(id int) error {\n    res, err := s.db.Exec("DELETE FROM questions WHERE id = ?", id)\n    if err != nil {\n        return err\n    }\n    if n, err := res.RowsAffected(); err != nil || n == 0 {\n        return ErrNotFound\n    }\n    return nil\n}',explain:[{at:'// internal/store/admin.go',to:'package store',text:'管理后台用到的数据访问，作为 UserStore 和 QuestionStore 的新方法，放在一个新文件里。'},{at:'func (s *UserStore) MigrateRoles(admins []string) error {',to:'return err',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行，用 WHERE name = \'role\' 看这一列存不存在。'},{at:'if n == 0 {',to:'return err',text:'没有才加：ALTER TABLE … ADD COLUMN 给已有的表加一列，已有的每一行都得到默认值 user。'},{at:'for _, name := range admins {',to:'return nil',text:'把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'func (s *UserStore) Role(',to:'return role, err',text:'查一个用户的角色。'},{at:'func (s *UserStore) SetRole(',to:'return err',text:'修改一个用户的角色。'},{at:'func (s *QuestionStore) CreateQuestion(',to:'return q, err',text:'新增题目：插入时不写 id，INTEGER PRIMARY KEY 会自动生成一个比现有最大值大的编号。'},{at:'id, err := res.LastInsertId()',to:'return q, err',text:'用 LastInsertId 取回自动生成的编号，放进返回的题目里。'},{at:'func (s *QuestionStore) UpdateQuestion(',to:'return nil',text:'修改题目：RowsAffected 是改了几行，0 行说明没有这道题。'},{at:'func (s *QuestionStore) DeleteQuestion(',to:'return nil',text:'删除题目，判断方法一样。练习题、学习记录里引用了它的行会留下，查询时连接题目表，自然就不出现了。'}]}},java:{practice:{steps:['新建 repository/AdminRepository.java，读懂已经给出的部分，补完 TODO。'],expect:'文件保存好即可，下一个任务把它用起来'},code:'// repository/AdminRepository.java\npackage com.example.zixishi.repository;\n\nimport com.example.zixishi.model.Question;\nimport java.util.List;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Repository\npublic class AdminRepository {\n\n    private final JdbcTemplate jdbc;\n\n    public AdminRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    // 给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员\n    @Transactional\n    public void migrateRoles(List<String> admins) {\n        Integer n = jdbc.queryForObject(\n            "SELECT COUNT(*) FROM pragma_table_info(\'users\') WHERE name = \'role\'", Integer.class);\n        if (n == 0) {\n            jdbc.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'");\n        }\n        for (String name : admins) {\n            jdbc.update("UPDATE users SET role = \'admin\' WHERE username = ?", name);\n        }\n    }\n\n    public String role(int userId) {\n        return jdbc.queryForList("SELECT role FROM users WHERE id = ?", String.class, userId)\n            .stream().findFirst().orElse("");\n    }\n\n    public void setRole(int userId, String role) {\n        jdbc.update("UPDATE users SET role = ? WHERE id = ?", role, userId);\n    }\n\n    // 新增一道题，编号由数据库自动生成\n    @Transactional\n    public Question createQuestion(Question q) {\n        jdbc.update("INSERT INTO questions (category, title, answer, difficulty) VALUES (?, ?, ?, ?)",\n            q.category(), q.title(), q.answer(), q.difficulty());\n        int id = jdbc.queryForObject("SELECT last_insert_rowid()", Integer.class);\n        return new Question(id, q.category(), q.title(), q.answer(), q.difficulty());\n    }\n\n    // 修改一道题，返回题目是否存在\n    public boolean updateQuestion(Question q) {\n        // TODO 1：UPDATE questions SET category = ?, title = ?, answer = ?, difficulty = ? WHERE id = ?；\n        //         jdbc.update 返回改了几行，大于 0 说明题目存在\n        return false;\n    }\n\n    // 删除一道题，返回题目是否存在\n    public boolean deleteQuestion(int id) {\n        // TODO 2：DELETE FROM questions WHERE id = ?，同样看 jdbc.update 的返回值\n        return false;\n    }\n}',explain:[{at:'// repository/AdminRepository.java',to:'import org.springframework.transaction.annotation.Transactional;',text:'管理后台用到的数据访问，放在一个新的仓库类里。'},{at:'@Repository',to:'this.jdbc = jdbc;',text:'和其他仓库类一样，通过构造函数拿到 JdbcTemplate。'},{at:'@Transactional',to:'jdbc.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'");',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行，用 WHERE name = \'role\' 数一数这一列在不在。没有才执行 ALTER TABLE … ADD COLUMN，已有的每一行都得到默认值 user。'},{at:'for (String name : admins) {',to:'jdbc.update("UPDATE users SET role = \'admin\' WHERE username = ?", name);',text:'把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'public String role(int userId) {',to:'.stream().findFirst().orElse("");',text:'查一个用户的角色；queryForList 查不到时是空列表，这时返回空字符串，不会抛异常。'},{at:'public void setRole(int userId, String role) {',to:'jdbc.update("UPDATE users SET role = ? WHERE id = ?", role, userId);',text:'修改一个用户的角色。'},{at:'// 新增一道题',to:'return new Question(id, q.category(), q.title(), q.answer(), q.difficulty());',text:'插入时不写 id，INTEGER PRIMARY KEY 会自动生成编号。SQLite 的 last_insert_rowid() 返回“这个连接上一次插入的编号”，所以两条语句要在同一个事务（同一个连接）里，方法上加了 @Transactional。'},{at:'public boolean updateQuestion(Question q) {',to:'return false;',text:'修改题目，要你补全。'},{at:'public boolean deleteQuestion(int id) {',to:'return false;',text:'删除题目，要你补全。'}],solution:{code:'// repository/AdminRepository.java\npackage com.example.zixishi.repository;\n\nimport com.example.zixishi.model.Question;\nimport java.util.List;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Repository\npublic class AdminRepository {\n\n    private final JdbcTemplate jdbc;\n\n    public AdminRepository(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    // 给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员\n    @Transactional\n    public void migrateRoles(List<String> admins) {\n        Integer n = jdbc.queryForObject(\n            "SELECT COUNT(*) FROM pragma_table_info(\'users\') WHERE name = \'role\'", Integer.class);\n        if (n == 0) {\n            jdbc.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'");\n        }\n        for (String name : admins) {\n            jdbc.update("UPDATE users SET role = \'admin\' WHERE username = ?", name);\n        }\n    }\n\n    public String role(int userId) {\n        return jdbc.queryForList("SELECT role FROM users WHERE id = ?", String.class, userId)\n            .stream().findFirst().orElse("");\n    }\n\n    public void setRole(int userId, String role) {\n        jdbc.update("UPDATE users SET role = ? WHERE id = ?", role, userId);\n    }\n\n    // 新增一道题，编号由数据库自动生成\n    @Transactional\n    public Question createQuestion(Question q) {\n        jdbc.update("INSERT INTO questions (category, title, answer, difficulty) VALUES (?, ?, ?, ?)",\n            q.category(), q.title(), q.answer(), q.difficulty());\n        int id = jdbc.queryForObject("SELECT last_insert_rowid()", Integer.class);\n        return new Question(id, q.category(), q.title(), q.answer(), q.difficulty());\n    }\n\n    // 修改一道题，返回题目是否存在\n    public boolean updateQuestion(Question q) {\n        int rows = jdbc.update("UPDATE questions SET category = ?, title = ?, answer = ?, difficulty = ? WHERE id = ?",\n            q.category(), q.title(), q.answer(), q.difficulty(), q.id());\n        return rows > 0;\n    }\n\n    // 删除一道题，返回题目是否存在\n    public boolean deleteQuestion(int id) {\n        return jdbc.update("DELETE FROM questions WHERE id = ?", id) > 0;\n    }\n}',explain:[{at:'// repository/AdminRepository.java',to:'import org.springframework.transaction.annotation.Transactional;',text:'管理后台用到的数据访问，放在一个新的仓库类里。'},{at:'@Repository',to:'this.jdbc = jdbc;',text:'和其他仓库类一样，通过构造函数拿到 JdbcTemplate。'},{at:'@Transactional',to:'jdbc.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'");',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行，用 WHERE name = \'role\' 数一数这一列在不在。没有才执行 ALTER TABLE … ADD COLUMN，已有的每一行都得到默认值 user。'},{at:'for (String name : admins) {',to:'jdbc.update("UPDATE users SET role = \'admin\' WHERE username = ?", name);',text:'把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'public String role(int userId) {',to:'.stream().findFirst().orElse("");',text:'查一个用户的角色；queryForList 查不到时是空列表，这时返回空字符串，不会抛异常。'},{at:'public void setRole(int userId, String role) {',to:'jdbc.update("UPDATE users SET role = ? WHERE id = ?", role, userId);',text:'修改一个用户的角色。'},{at:'// 新增一道题',to:'return new Question(id, q.category(), q.title(), q.answer(), q.difficulty());',text:'插入时不写 id，INTEGER PRIMARY KEY 会自动生成编号。SQLite 的 last_insert_rowid() 返回“这个连接上一次插入的编号”，所以两条语句要在同一个事务（同一个连接）里，方法上加了 @Transactional。'},{at:'public boolean updateQuestion(Question q) {',to:'return rows > 0;',text:'修改题目：jdbc.update 返回受影响的行数，0 行说明没有这道题。'},{at:'public boolean deleteQuestion(int id) {',to:'return jdbc.update("DELETE FROM questions WHERE id = ?", id) > 0;',text:'删除题目，同样看删了几行。'}]}},node:{practice:{steps:['新建 src/db/admin.js，读懂已经给出的部分，补完 TODO。'],expect:'文件保存好即可，下一个任务把它用起来'},code:'// src/db/admin.js\nconst { db } = require("./database");\n\n// 给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员\nfunction migrateRoles(admins) {\n  const columns = db.prepare("SELECT name FROM pragma_table_info(\'users\')").all().map((c) => c.name);\n  if (!columns.includes("role")) db.exec("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'");\n  const promote = db.prepare("UPDATE users SET role = \'admin\' WHERE username = ?");\n  for (const name of admins) promote.run(name);\n}\n\nfunction getRole(userId) {\n  return db.prepare("SELECT role FROM users WHERE id = ?").get(userId)?.role;\n}\n\nfunction setRole(userId, role) {\n  db.prepare("UPDATE users SET role = ? WHERE id = ?").run(role, userId);\n}\n\n// 新增一道题，编号由数据库自动生成\nfunction createQuestion(q) {\n  const result = db\n    .prepare("INSERT INTO questions (category, title, answer, difficulty) VALUES (@category, @title, @answer, @difficulty)")\n    .run(q);\n  return { id: Number(result.lastInsertRowid), ...q };\n}\n\n// 修改一道题，返回是否存在\nfunction updateQuestion(id, q) {\n  // TODO 1：UPDATE questions SET category = @category, title = @title, answer = @answer, difficulty = @difficulty WHERE id = @id；\n  //         run 的结果里 changes 是改了几行，大于 0 说明题目存在\n}\n\n// 删除一道题，返回是否存在\nfunction deleteQuestion(id) {\n  // TODO 2：DELETE FROM questions WHERE id = ?，同样用 changes 判断\n}\n\nmodule.exports = { migrateRoles, getRole, setRole, createQuestion, updateQuestion, deleteQuestion };',explain:[{at:'// src/db/admin.js',to:'const { db } = require("./database");',text:'管理后台用到的数据访问。'},{at:'function migrateRoles(admins) {',to:'for (const name of admins) promote.run(name);',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行。没有 role 列才执行 ALTER TABLE … ADD COLUMN，已有的每一行都得到默认值 user。然后把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'function getRole(userId) {',to:'return db.prepare(',text:'查一个用户的角色。'},{at:'function setRole(userId, role) {',to:'db.prepare("UPDATE users SET role = ? WHERE id = ?")',text:'修改一个用户的角色。'},{at:'function createQuestion(q) {',to:'return { id: Number(result.lastInsertRowid), ...q };',text:'新增题目：插入时不写 id，INTEGER PRIMARY KEY 会自动生成编号。'},{at:'function updateQuestion(id, q) {',text:'修改题目，要你补全。'},{at:'function deleteQuestion(id) {',text:'删除题目，要你补全。'},{at:'module.exports =',text:'导出。'}],solution:{code:'// src/db/admin.js\nconst { db } = require("./database");\n\n// 给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员\nfunction migrateRoles(admins) {\n  const columns = db.prepare("SELECT name FROM pragma_table_info(\'users\')").all().map((c) => c.name);\n  if (!columns.includes("role")) db.exec("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'");\n  const promote = db.prepare("UPDATE users SET role = \'admin\' WHERE username = ?");\n  for (const name of admins) promote.run(name);\n}\n\nfunction getRole(userId) {\n  return db.prepare("SELECT role FROM users WHERE id = ?").get(userId)?.role;\n}\n\nfunction setRole(userId, role) {\n  db.prepare("UPDATE users SET role = ? WHERE id = ?").run(role, userId);\n}\n\n// 新增一道题，编号由数据库自动生成\nfunction createQuestion(q) {\n  const result = db\n    .prepare("INSERT INTO questions (category, title, answer, difficulty) VALUES (@category, @title, @answer, @difficulty)")\n    .run(q);\n  return { id: Number(result.lastInsertRowid), ...q };\n}\n\n// 修改一道题，返回是否存在\nfunction updateQuestion(id, q) {\n  const result = db\n    .prepare("UPDATE questions SET category = @category, title = @title, answer = @answer, difficulty = @difficulty WHERE id = @id")\n    .run({ ...q, id });\n  return result.changes > 0;\n}\n\n// 删除一道题，返回是否存在\nfunction deleteQuestion(id) {\n  return db.prepare("DELETE FROM questions WHERE id = ?").run(id).changes > 0;\n}\n\nmodule.exports = { migrateRoles, getRole, setRole, createQuestion, updateQuestion, deleteQuestion };',explain:[{at:'// src/db/admin.js',to:'const { db } = require("./database");',text:'管理后台用到的数据访问。'},{at:'function migrateRoles(admins) {',to:'for (const name of admins) promote.run(name);',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行。没有 role 列才执行 ALTER TABLE … ADD COLUMN，已有的每一行都得到默认值 user。然后把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'function getRole(userId) {',to:'return db.prepare(',text:'查一个用户的角色。'},{at:'function setRole(userId, role) {',to:'db.prepare("UPDATE users SET role = ? WHERE id = ?")',text:'修改一个用户的角色。'},{at:'function createQuestion(q) {',to:'return { id: Number(result.lastInsertRowid), ...q };',text:'新增题目：插入时不写 id，INTEGER PRIMARY KEY 会自动生成编号。'},{at:'function updateQuestion(id, q) {',to:'return result.changes > 0;',text:'修改题目：命名占位符从对象里取值，{ ...q, id } 把编号也放进去。改了 0 行说明没有这道题。'},{at:'function deleteQuestion(id) {',to:'return db.prepare("DELETE FROM questions WHERE id = ?")',text:'删除题目，同样看删了几行。'},{at:'module.exports =',text:'导出。'}]}},python:{practice:{steps:['新建 app/admin_db.py，读懂已经给出的部分，补完 TODO。'],expect:'文件保存好即可，下一个任务把它用起来'},code:'# app/admin_db.py\nfrom contextlib import closing\n\nfrom app.database import connect, query_one\n\n\ndef migrate_roles(admins):\n    """给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员"""\n    with closing(connect()) as conn:\n        with conn:\n            columns = [row["name"] for row in conn.execute("SELECT name FROM pragma_table_info(\'users\')")]\n            if "role" not in columns:\n                conn.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'")\n            for name in admins:\n                conn.execute("UPDATE users SET role = \'admin\' WHERE username = ?", (name,))\n\n\ndef get_role(user_id):\n    row = query_one("SELECT role FROM users WHERE id = ?", (user_id,))\n    return row["role"] if row else None\n\n\ndef set_role(user_id, role):\n    with closing(connect()) as conn:\n        with conn:\n            conn.execute("UPDATE users SET role = ? WHERE id = ?", (role, user_id))\n\n\ndef create_question(q):\n    """新增一道题，编号由数据库自动生成"""\n    with closing(connect()) as conn:\n        with conn:\n            cur = conn.execute(\n                "INSERT INTO questions (category, title, answer, difficulty) "\n                "VALUES (:category, :title, :answer, :difficulty)", q)\n    return {"id": cur.lastrowid, **q}\n\n\ndef update_question(qid, q):\n    """修改一道题，返回题目是否存在"""\n    # TODO 1：UPDATE questions SET category = :category, title = :title, answer = :answer,\n    #         difficulty = :difficulty WHERE id = :id（参数用 {**q, "id": qid}）；\n    #         cur.rowcount 是改了几行，大于 0 说明题目存在\n    return False\n\n\ndef delete_question(qid):\n    """删除一道题，返回题目是否存在"""\n    # TODO 2：DELETE FROM questions WHERE id = ?，同样用 rowcount 判断\n    return False',explain:[{at:'# app/admin_db.py',to:'from app.database import connect, query_one',text:'管理后台用到的数据访问，放在一个新文件里。connect 和 query_one 是第 6 关写的工具函数。'},{at:'def migrate_roles(admins):',to:'conn.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'")',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行，name 是列名。没有 role 列才执行 ALTER TABLE … ADD COLUMN，已有的每一行都得到默认值 user。'},{at:'for name in admins:',to:'conn.execute("UPDATE users SET role = \'admin\' WHERE username = ?", (name,))',text:'把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'def get_role(user_id):',to:'return row["role"] if row else None',text:'查一个用户的角色，用户不存在时返回 None。'},{at:'def set_role(user_id, role):',to:'conn.execute("UPDATE users SET role = ? WHERE id = ?", (role, user_id))',text:'修改一个用户的角色。with conn: 结束时自动提交。'},{at:'def create_question(q):',to:'return {"id": cur.lastrowid, **q}',text:'新增题目：插入时不写 id，INTEGER PRIMARY KEY 会自动生成编号，用 lastrowid 取回来。:category 这种写法是“命名占位符”，值从字典 q 里按名字取。'},{at:'def update_question(qid, q):',to:'return False',text:'修改题目，要你补全。'},{at:'def delete_question(qid):',to:'return False',text:'删除题目，要你补全。'}],solution:{code:'# app/admin_db.py\nfrom contextlib import closing\n\nfrom app.database import connect, query_one\n\n\ndef migrate_roles(admins):\n    """给 users 表加上 role 列（已经有了就跳过），再把 admins 里的用户名设成管理员"""\n    with closing(connect()) as conn:\n        with conn:\n            columns = [row["name"] for row in conn.execute("SELECT name FROM pragma_table_info(\'users\')")]\n            if "role" not in columns:\n                conn.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'")\n            for name in admins:\n                conn.execute("UPDATE users SET role = \'admin\' WHERE username = ?", (name,))\n\n\ndef get_role(user_id):\n    row = query_one("SELECT role FROM users WHERE id = ?", (user_id,))\n    return row["role"] if row else None\n\n\ndef set_role(user_id, role):\n    with closing(connect()) as conn:\n        with conn:\n            conn.execute("UPDATE users SET role = ? WHERE id = ?", (role, user_id))\n\n\ndef create_question(q):\n    """新增一道题，编号由数据库自动生成"""\n    with closing(connect()) as conn:\n        with conn:\n            cur = conn.execute(\n                "INSERT INTO questions (category, title, answer, difficulty) "\n                "VALUES (:category, :title, :answer, :difficulty)", q)\n    return {"id": cur.lastrowid, **q}\n\n\ndef update_question(qid, q):\n    """修改一道题，返回题目是否存在"""\n    with closing(connect()) as conn:\n        with conn:\n            cur = conn.execute(\n                "UPDATE questions SET category = :category, title = :title, answer = :answer, "\n                "difficulty = :difficulty WHERE id = :id", {**q, "id": qid})\n    return cur.rowcount > 0\n\n\ndef delete_question(qid):\n    """删除一道题，返回题目是否存在"""\n    with closing(connect()) as conn:\n        with conn:\n            cur = conn.execute("DELETE FROM questions WHERE id = ?", (qid,))\n    return cur.rowcount > 0',explain:[{at:'# app/admin_db.py',to:'from app.database import connect, query_one',text:'管理后台用到的数据访问，放在一个新文件里。connect 和 query_one 是第 6 关写的工具函数。'},{at:'def migrate_roles(admins):',to:'conn.execute("ALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT \'user\'")',text:'pragma_table_info(\'users\') 是 SQLite 提供的“表结构查询”，每一列是一行，name 是列名。没有 role 列才执行 ALTER TABLE … ADD COLUMN，已有的每一行都得到默认值 user。'},{at:'for name in admins:',to:'conn.execute("UPDATE users SET role = \'admin\' WHERE username = ?", (name,))',text:'把 ADMIN_USERNAMES 里已经注册的账号设成管理员。'},{at:'def get_role(user_id):',to:'return row["role"] if row else None',text:'查一个用户的角色，用户不存在时返回 None。'},{at:'def set_role(user_id, role):',to:'conn.execute("UPDATE users SET role = ? WHERE id = ?", (role, user_id))',text:'修改一个用户的角色。with conn: 结束时自动提交。'},{at:'def create_question(q):',to:'return {"id": cur.lastrowid, **q}',text:'新增题目：插入时不写 id，INTEGER PRIMARY KEY 会自动生成编号，用 lastrowid 取回来。:category 这种写法是“命名占位符”，值从字典 q 里按名字取。'},{at:'def update_question(qid, q):',to:'return cur.rowcount > 0',text:'修改题目：{**q, "id": qid} 把题目字典和编号合成一个字典，给命名占位符取值。rowcount 是改了几行，0 行说明没有这道题。'},{at:'def delete_question(qid):',to:'return cur.rowcount > 0',text:'删除题目，同样看删了几行。'}]}}}},
  {title:'任务二：权限、校验和管理接口',body:'业务逻辑层：判断管理员、检查题目、调用数据访问层；处理请求的层（已经给出）：三个接口都先认人、再看角色。最后让注册成功的名单用户自动成为管理员。',variants:{go:{practice:{steps:['新建 internal/service/admin.go（代码第一部分），补完 TODO。','新建 internal/handler/admin.go（第二部分，已经给出），按最后的注释修改 handler.go、auth.go 和 main.go。','设置 ADMIN_USERNAMES=你的用户名 重启，登录后用 curl 或页面新增一道题。'],expect:'POST /api/admin/questions {"category":"go","title":"…","answer":"…","difficulty":1}\n→ 201 {"id":25,"category":"go","title":"…","answer":"…","difficulty":1}'},code:'// internal/service/admin.go\npackage service\n\nimport (\n    "errors"\n    "regexp"\n    "strings"\n    "unicode/utf8"\n\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrForbidden       = errors.New("需要管理员权限")\n    ErrInvalidQuestion = errors.New("科目要 1–20 个小写字母、数字或横线，题目 1–200 字，答案 1–2000 字，难度 1–3")\n)\n\nvar categoryPattern = regexp.MustCompile(`^[a-z0-9-]{1,20}$`)\n\ntype AdminService struct {\n    users     *store.UserStore\n    questions *store.QuestionStore\n    admins    map[string]bool\n}\n\n// NewAdminService 记下哪些用户名是管理员（来自环境变量 ADMIN_USERNAMES，逗号隔开）。\nfunc NewAdminService(users *store.UserStore, questions *store.QuestionStore, adminNames []string) *AdminService {\n    admins := map[string]bool{}\n    for _, name := range adminNames {\n        admins[name] = true\n    }\n    return &AdminService{users: users, questions: questions, admins: admins}\n}\n\n// OnRegister 在注册成功后调用：名单里的用户名自动成为管理员。\nfunc (s *AdminService) OnRegister(u store.User) error {\n    if !s.admins[u.Username] {\n        return nil\n    }\n    return s.users.SetRole(u.ID, "admin")\n}\n\n// RequireAdmin 判断用户是不是管理员，不是时返回 ErrForbidden。\nfunc (s *AdminService) RequireAdmin(u store.User) error {\n    // TODO 1：用 s.users.Role 查出角色（出错直接返回），不是 "admin" 返回 ErrForbidden\n    return nil\n}\n\n// clean 去掉首尾空格并检查题目是否合格。\nfunc clean(q store.Question) (store.Question, error) {\n    q.Category = strings.TrimSpace(q.Category)\n    q.Title = strings.TrimSpace(q.Title)\n    q.Answer = strings.TrimSpace(q.Answer)\n    titleLen, answerLen := utf8.RuneCountInString(q.Title), utf8.RuneCountInString(q.Answer)\n    // TODO 2：科目要匹配 categoryPattern，题目 1–200 字、答案 1–2000 字，难度 1–3；不合格返回 ErrInvalidQuestion\n    _, _ = titleLen, answerLen\n    return q, nil\n}\n\nfunc (s *AdminService) Create(q store.Question) (store.Question, error) {\n    // TODO 3：先 clean，再 s.questions.CreateQuestion\n    return q, nil\n}\n\nfunc (s *AdminService) Update(q store.Question) (store.Question, error) {\n    // TODO 4：先 clean，再 s.questions.UpdateQuestion\n    return q, nil\n}\n\nfunc (s *AdminService) Delete(id int) error {\n    return s.questions.DeleteQuestion(id)\n}\n\n// internal/handler/admin.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "log"\n    "net/http"\n    "strconv"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// requireAdmin 先认人（没登录 401），再看角色（不是管理员 403）。\nfunc (h *Handler) requireAdmin(w http.ResponseWriter, r *http.Request) (store.User, bool) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return u, false\n    }\n    if err := h.admin.RequireAdmin(u); err != nil {\n        h.adminError(w, err)\n        return u, false\n    }\n    return u, true\n}\n\nfunc (h *Handler) adminError(w http.ResponseWriter, err error) {\n    switch {\n    case errors.Is(err, service.ErrForbidden):\n        writeJSON(w, http.StatusForbidden, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrInvalidQuestion):\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})\n    case errors.Is(err, store.ErrNotFound):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": "题目不存在"})\n    default:\n        h.serverError(w, err)\n    }\n}\n\n// readQuestion 读出请求正文里的题目；路径里有编号时一并填上。\nfunc readQuestion(r *http.Request) (store.Question, error) {\n    var q store.Question\n    if err := json.NewDecoder(r.Body).Decode(&q); err != nil {\n        return q, service.ErrInvalidQuestion\n    }\n    if idText := r.PathValue("id"); idText != "" {\n        id, err := strconv.Atoi(idText)\n        if err != nil {\n            return q, store.ErrNotFound\n        }\n        q.ID = id\n    }\n    return q, nil\n}\n\nfunc (h *Handler) adminCreate(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireAdmin(w, r)\n    if !ok {\n        return\n    }\n    q, err := readQuestion(r)\n    if err == nil {\n        q, err = h.admin.Create(q)\n    }\n    if err != nil {\n        h.adminError(w, err)\n        return\n    }\n    log.Printf("管理员 %s 新增了第 %d 题", u.Username, q.ID)\n    writeJSON(w, http.StatusCreated, q)\n}\n\nfunc (h *Handler) adminUpdate(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireAdmin(w, r)\n    if !ok {\n        return\n    }\n    q, err := readQuestion(r)\n    if err == nil {\n        q, err = h.admin.Update(q)\n    }\n    if err != nil {\n        h.adminError(w, err)\n        return\n    }\n    log.Printf("管理员 %s 修改了第 %d 题", u.Username, q.ID)\n    writeJSON(w, http.StatusOK, q)\n}\n\nfunc (h *Handler) adminDelete(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireAdmin(w, r)\n    if !ok {\n        return\n    }\n    id, err := strconv.Atoi(r.PathValue("id"))\n    if err != nil {\n        err = store.ErrNotFound\n    } else {\n        err = h.admin.Delete(id)\n    }\n    if err != nil {\n        h.adminError(w, err)\n        return\n    }\n    log.Printf("管理员 %s 删除了第 %d 题", u.Username, id)\n    w.WriteHeader(http.StatusNoContent)\n}\n\n// 组装：\n// handler.go：Handler 加上字段 admin *service.AdminService，New 多一个参数（放在 oauth 后面）；Routes 里加上：\n//     mux.HandleFunc("POST /api/admin/questions", h.adminCreate)\n//     mux.HandleFunc("PUT /api/admin/questions/{id}", h.adminUpdate)\n//     mux.HandleFunc("DELETE /api/admin/questions/{id}", h.adminDelete)\n// auth.go 的 register 里，注册成功、返回 201 之前加上：h.admin.OnRegister(u)\n// main.go 里创建 oauth 之后加上，再把 admin 传给 handler.New：\nadminNames := strings.Split(os.Getenv("ADMIN_USERNAMES"), ",")\nif err := us.MigrateRoles(adminNames); err != nil {\n    log.Fatalf("迁移角色列失败：%v", err)\n}\nadmin := service.NewAdminService(us, qs, adminNames)',explain:[{at:'// internal/service/admin.go',to:'"zixishi/internal/store"',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。'},{at:'var (',to:'ErrInvalidQuestion = errors.New(',text:'两种错误：没有权限（403）、题目不合格（400）。'},{at:'var categoryPattern =',text:'科目名的规则：1 到 20 个小写字母、数字或横线。'},{at:'type AdminService struct {',to:'admins    map[string]bool',text:'admins 是“用户名 → 是不是管理员”的 map，用来快速判断名单。'},{at:'func NewAdminService(',to:'return &AdminService{',text:'把名单转成 map。'},{at:'func (s *AdminService) OnRegister(',to:'return s.users.SetRole(u.ID, "admin")',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'func (s *AdminService) RequireAdmin(',to:'return nil',text:'判断管理员，要你补全。'},{at:'func clean(',to:'titleLen, answerLen := utf8.RuneCountInString(',text:'先去掉首尾空格，再按字数算长度（RuneCountInString 一个汉字算 1，len 算的是字节数，一个汉字是 3）。'},{at:'// TODO 2',to:'return q, nil',text:'逐项检查，要你补全。_, _ = … 只是让还没用到的变量先能编译，写完就删掉。'},{at:'func (s *AdminService) Create(',to:'return q, nil',text:'新增，要你补全。'},{at:'func (s *AdminService) Update(',to:'return q, nil',text:'修改，要你补全。'},{at:'func (s *AdminService) Delete(',to:'return s.questions.DeleteQuestion(id)',text:'删除直接交给数据访问层。'},{at:'// internal/handler/admin.go',to:'"zixishi/internal/store"',text:'三个管理接口，已经给出，读懂就行。'},{at:'func (h *Handler) requireAdmin(',to:'return u, true',text:'先认人（requireUser 没登录时已经写好 401），再看角色（不是管理员 403）。所有管理接口一开头都调用它。'},{at:'func (h *Handler) adminError(',to:'h.serverError(w, err)',text:'错误翻译成状态码：403、400、404、500。'},{at:'func readQuestion(',to:'return q, nil',text:'正文直接解析成 store.Question（json 标签是 category、title、answer、difficulty）；不是合法 JSON 当作不合格。修改时编号来自路径，而不是正文。'},{at:'func (h *Handler) adminCreate(',to:'writeJSON(w, http.StatusCreated, q)',text:'新增：成功返回 201 和新题目，并记一行日志：谁在什么时候做了什么（简单的审计）。'},{at:'func (h *Handler) adminUpdate(',to:'writeJSON(w, http.StatusOK, q)',text:'修改：成功返回 200 和修改后的题目。'},{at:'func (h *Handler) adminDelete(',to:'w.WriteHeader(http.StatusNoContent)',text:'删除：成功返回 204（没有正文）。'},{at:'adminNames := strings.Split(',to:'admin := service.NewAdminService(us, qs, adminNames)',text:'读出管理员名单（main.go 的 import 里加上 "strings"），迁移角色列并设置已有的管理员，组装管理服务。'}],solution:{code:'// internal/service/admin.go\npackage service\n\nimport (\n    "errors"\n    "regexp"\n    "strings"\n    "unicode/utf8"\n\n    "zixishi/internal/store"\n)\n\nvar (\n    ErrForbidden       = errors.New("需要管理员权限")\n    ErrInvalidQuestion = errors.New("科目要 1–20 个小写字母、数字或横线，题目 1–200 字，答案 1–2000 字，难度 1–3")\n)\n\nvar categoryPattern = regexp.MustCompile(`^[a-z0-9-]{1,20}$`)\n\ntype AdminService struct {\n    users     *store.UserStore\n    questions *store.QuestionStore\n    admins    map[string]bool\n}\n\n// NewAdminService 记下哪些用户名是管理员（来自环境变量 ADMIN_USERNAMES，逗号隔开）。\nfunc NewAdminService(users *store.UserStore, questions *store.QuestionStore, adminNames []string) *AdminService {\n    admins := map[string]bool{}\n    for _, name := range adminNames {\n        admins[name] = true\n    }\n    return &AdminService{users: users, questions: questions, admins: admins}\n}\n\n// OnRegister 在注册成功后调用：名单里的用户名自动成为管理员。\nfunc (s *AdminService) OnRegister(u store.User) error {\n    if !s.admins[u.Username] {\n        return nil\n    }\n    return s.users.SetRole(u.ID, "admin")\n}\n\n// RequireAdmin 判断用户是不是管理员，不是时返回 ErrForbidden。\nfunc (s *AdminService) RequireAdmin(u store.User) error {\n    role, err := s.users.Role(u.ID)\n    if err != nil {\n        return err\n    }\n    if role != "admin" {\n        return ErrForbidden\n    }\n    return nil\n}\n\n// clean 去掉首尾空格并检查题目是否合格。\nfunc clean(q store.Question) (store.Question, error) {\n    q.Category = strings.TrimSpace(q.Category)\n    q.Title = strings.TrimSpace(q.Title)\n    q.Answer = strings.TrimSpace(q.Answer)\n    titleLen, answerLen := utf8.RuneCountInString(q.Title), utf8.RuneCountInString(q.Answer)\n    if !categoryPattern.MatchString(q.Category) || titleLen < 1 || titleLen > 200 ||\n        answerLen < 1 || answerLen > 2000 || q.Difficulty < 1 || q.Difficulty > 3 {\n        return q, ErrInvalidQuestion\n    }\n    return q, nil\n}\n\nfunc (s *AdminService) Create(q store.Question) (store.Question, error) {\n    q, err := clean(q)\n    if err != nil {\n        return q, err\n    }\n    return s.questions.CreateQuestion(q)\n}\n\nfunc (s *AdminService) Update(q store.Question) (store.Question, error) {\n    q, err := clean(q)\n    if err != nil {\n        return q, err\n    }\n    return q, s.questions.UpdateQuestion(q)\n}\n\nfunc (s *AdminService) Delete(id int) error {\n    return s.questions.DeleteQuestion(id)\n}\n\n// internal/handler/admin.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "log"\n    "net/http"\n    "strconv"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// requireAdmin 先认人（没登录 401），再看角色（不是管理员 403）。\nfunc (h *Handler) requireAdmin(w http.ResponseWriter, r *http.Request) (store.User, bool) {\n    u, ok := h.requireUser(w, r)\n    if !ok {\n        return u, false\n    }\n    if err := h.admin.RequireAdmin(u); err != nil {\n        h.adminError(w, err)\n        return u, false\n    }\n    return u, true\n}\n\nfunc (h *Handler) adminError(w http.ResponseWriter, err error) {\n    switch {\n    case errors.Is(err, service.ErrForbidden):\n        writeJSON(w, http.StatusForbidden, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrInvalidQuestion):\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})\n    case errors.Is(err, store.ErrNotFound):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": "题目不存在"})\n    default:\n        h.serverError(w, err)\n    }\n}\n\n// readQuestion 读出请求正文里的题目；路径里有编号时一并填上。\nfunc readQuestion(r *http.Request) (store.Question, error) {\n    var q store.Question\n    if err := json.NewDecoder(r.Body).Decode(&q); err != nil {\n        return q, service.ErrInvalidQuestion\n    }\n    if idText := r.PathValue("id"); idText != "" {\n        id, err := strconv.Atoi(idText)\n        if err != nil {\n            return q, store.ErrNotFound\n        }\n        q.ID = id\n    }\n    return q, nil\n}\n\nfunc (h *Handler) adminCreate(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireAdmin(w, r)\n    if !ok {\n        return\n    }\n    q, err := readQuestion(r)\n    if err == nil {\n        q, err = h.admin.Create(q)\n    }\n    if err != nil {\n        h.adminError(w, err)\n        return\n    }\n    log.Printf("管理员 %s 新增了第 %d 题", u.Username, q.ID)\n    writeJSON(w, http.StatusCreated, q)\n}\n\nfunc (h *Handler) adminUpdate(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireAdmin(w, r)\n    if !ok {\n        return\n    }\n    q, err := readQuestion(r)\n    if err == nil {\n        q, err = h.admin.Update(q)\n    }\n    if err != nil {\n        h.adminError(w, err)\n        return\n    }\n    log.Printf("管理员 %s 修改了第 %d 题", u.Username, q.ID)\n    writeJSON(w, http.StatusOK, q)\n}\n\nfunc (h *Handler) adminDelete(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.requireAdmin(w, r)\n    if !ok {\n        return\n    }\n    id, err := strconv.Atoi(r.PathValue("id"))\n    if err != nil {\n        err = store.ErrNotFound\n    } else {\n        err = h.admin.Delete(id)\n    }\n    if err != nil {\n        h.adminError(w, err)\n        return\n    }\n    log.Printf("管理员 %s 删除了第 %d 题", u.Username, id)\n    w.WriteHeader(http.StatusNoContent)\n}\n\n// 组装：\n// handler.go：Handler 加上字段 admin *service.AdminService，New 多一个参数（放在 oauth 后面）；Routes 里加上：\n//     mux.HandleFunc("POST /api/admin/questions", h.adminCreate)\n//     mux.HandleFunc("PUT /api/admin/questions/{id}", h.adminUpdate)\n//     mux.HandleFunc("DELETE /api/admin/questions/{id}", h.adminDelete)\n// auth.go 的 register 里，注册成功、返回 201 之前加上：h.admin.OnRegister(u)\n// main.go 里创建 oauth 之后加上，再把 admin 传给 handler.New：\nadminNames := strings.Split(os.Getenv("ADMIN_USERNAMES"), ",")\nif err := us.MigrateRoles(adminNames); err != nil {\n    log.Fatalf("迁移角色列失败：%v", err)\n}\nadmin := service.NewAdminService(us, qs, adminNames)',explain:[{at:'// internal/service/admin.go',to:'"zixishi/internal/store"',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。'},{at:'var (',to:'ErrInvalidQuestion = errors.New(',text:'两种错误：没有权限（403）、题目不合格（400）。'},{at:'var categoryPattern =',text:'科目名的规则：1 到 20 个小写字母、数字或横线。'},{at:'type AdminService struct {',to:'admins    map[string]bool',text:'admins 是“用户名 → 是不是管理员”的 map，用来快速判断名单。'},{at:'func NewAdminService(',to:'return &AdminService{',text:'把名单转成 map。'},{at:'func (s *AdminService) OnRegister(',to:'return s.users.SetRole(u.ID, "admin")',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'func (s *AdminService) RequireAdmin(',to:'return nil',text:'从数据库查出角色，不是 admin 就是没有权限。每次请求都查一次数据库，改了角色马上生效。'},{at:'func clean(',to:'return q, nil',text:'去掉首尾空格后逐项检查。RuneCountInString 按字数算，一个汉字算 1。'},{at:'func (s *AdminService) Create(',to:'return s.questions.CreateQuestion(q)',text:'检查合格再保存。'},{at:'func (s *AdminService) Update(',to:'return q, s.questions.UpdateQuestion(q)',text:'检查合格再修改，不存在时数据访问层返回 ErrNotFound。'},{at:'func (s *AdminService) Delete(',to:'return s.questions.DeleteQuestion(id)',text:'删除直接交给数据访问层。'},{at:'// internal/handler/admin.go',to:'"zixishi/internal/store"',text:'三个管理接口，已经给出，读懂就行。'},{at:'func (h *Handler) requireAdmin(',to:'return u, true',text:'先认人（requireUser 没登录时已经写好 401），再看角色（不是管理员 403）。所有管理接口一开头都调用它。'},{at:'func (h *Handler) adminError(',to:'h.serverError(w, err)',text:'错误翻译成状态码：403、400、404、500。'},{at:'func readQuestion(',to:'return q, nil',text:'正文直接解析成 store.Question（json 标签是 category、title、answer、difficulty）；不是合法 JSON 当作不合格。修改时编号来自路径，而不是正文。'},{at:'func (h *Handler) adminCreate(',to:'writeJSON(w, http.StatusCreated, q)',text:'新增：成功返回 201 和新题目，并记一行日志：谁在什么时候做了什么（简单的审计）。'},{at:'func (h *Handler) adminUpdate(',to:'writeJSON(w, http.StatusOK, q)',text:'修改：成功返回 200 和修改后的题目。'},{at:'func (h *Handler) adminDelete(',to:'w.WriteHeader(http.StatusNoContent)',text:'删除：成功返回 204（没有正文）。'},{at:'adminNames := strings.Split(',to:'admin := service.NewAdminService(us, qs, adminNames)',text:'读出管理员名单（main.go 的 import 里加上 "strings"），迁移角色列并设置已有的管理员，组装管理服务。'}]}},java:{practice:{steps:['新建 service/AdminService.java（代码第一部分），补完 TODO。','新建 controller/AdminController.java（已经给出），按最后的注释修改 AuthController.java。','设置环境变量 ADMIN_USERNAMES=你的用户名 重启，登录后用 curl 或页面新增一道题。'],expect:'POST /api/admin/questions {"category":"go","title":"…","answer":"…","difficulty":1}\n→ 201 {"id":25,"category":"go","title":"…","answer":"…","difficulty":1}'},code:'// service/AdminService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.repository.AdminRepository;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.regex.Pattern;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class AdminService implements ApplicationRunner {\n\n    private static final Pattern CATEGORY = Pattern.compile("[a-z0-9-]{1,20}");\n\n    private final AdminRepository repo;\n    private final List<String> admins;\n\n    public AdminService(AdminRepository repo, @Value("${ADMIN_USERNAMES:}") String adminNames) {\n        this.repo = repo;\n        this.admins = Arrays.stream(adminNames.split(",")).map(String::strip).filter(s -> !s.isEmpty()).toList();\n    }\n\n    // 服务启动完成后 Spring Boot 自动调用：迁移角色列，设置名单里已经注册的管理员\n    @Override\n    public void run(ApplicationArguments args) {\n        repo.migrateRoles(admins);\n    }\n\n    // 注册成功后调用：名单里的用户名自动成为管理员\n    public void onRegister(User user) {\n        if (admins.contains(user.username())) {\n            repo.setRole(user.id(), "admin");\n        }\n    }\n\n    private static StudyService.StudyException error(int status, String message) {\n        return new StudyService.StudyException(status, message);\n    }\n\n    // 不是管理员时抛出 error(403, "需要管理员权限")\n    public void requireAdmin(User user) {\n        // TODO 1：用 repo.role 查出角色，不是 "admin" 就抛出 403\n    }\n\n    // 去掉首尾空格并检查题目是否合格，合格时返回 new Question(id, 科目, 题目, 答案, 难度)\n    public Question clean(int id, String category, String title, String answer, Integer difficulty) {\n        // TODO 2：三段文字是 null 时当成 ""，再 strip 去掉首尾空格；科目要 CATEGORY.matcher(…).matches()，\n        //         题目 1–200 字、答案 1–2000 字（用 codePointCount 数字数），难度不是 null 且在 1–3；\n        //         不合格抛出 error(400, …)\n        return null;\n    }\n\n    public Question create(Question q) {\n        // TODO 3：repo.createQuestion（q 已经 clean 过）\n        return null;\n    }\n\n    public Question update(Question q) {\n        // TODO 4：repo.updateQuestion 返回 false 时抛出 error(404, "题目不存在")，否则返回 q\n        return null;\n    }\n\n    public void delete(int id) {\n        // TODO 5：repo.deleteQuestion 返回 false 时抛出 error(404, "题目不存在")\n    }\n}\n\n// controller/AdminController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.service.AdminService;\nimport com.example.zixishi.service.AuthService;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api/admin")\npublic class AdminController {\n\n    private static final Logger log = LoggerFactory.getLogger(AdminController.class);\n\n    public record QuestionBody(String category, String title, String answer, Integer difficulty) {}\n\n    private final AuthService auth;\n    private final AdminService admin;\n\n    public AdminController(AuthService auth, AdminService admin) {\n        this.auth = auth;\n        this.admin = admin;\n    }\n\n    // 先认人（没登录 401），再看角色（不是管理员 403）\n    private User requireAdmin(String token) {\n        User user = auth.currentUser(token);\n        admin.requireAdmin(user);\n        return user;\n    }\n\n    @PostMapping("/questions")\n    public ResponseEntity<Question> create(@CookieValue(name = "session", required = false) String token,\n                                           @RequestBody QuestionBody body) {\n        User user = requireAdmin(token);\n        Question q = admin.create(admin.clean(0, body.category(), body.title(), body.answer(), body.difficulty()));\n        log.info("管理员 {} 新增了第 {} 题", user.username(), q.id());\n        return ResponseEntity.status(201).body(q);\n    }\n\n    @PutMapping("/questions/{id}")\n    public Question update(@CookieValue(name = "session", required = false) String token,\n                           @PathVariable int id, @RequestBody QuestionBody body) {\n        User user = requireAdmin(token);\n        Question q = admin.update(admin.clean(id, body.category(), body.title(), body.answer(), body.difficulty()));\n        log.info("管理员 {} 修改了第 {} 题", user.username(), id);\n        return q;\n    }\n\n    @DeleteMapping("/questions/{id}")\n    public ResponseEntity<Void> delete(@CookieValue(name = "session", required = false) String token,\n                                       @PathVariable int id) {\n        User user = requireAdmin(token);\n        admin.delete(id);\n        log.info("管理员 {} 删除了第 {} 题", user.username(), id);\n        return ResponseEntity.noContent().build();\n    }\n}\n\n// controller/AuthController.java：注入 AdminService（加字段和构造函数参数），注册方法改成\n@PostMapping("/register")\npublic ResponseEntity<User> register(@RequestBody Credentials body) {\n    User user = auth.register(body.username(), body.password());\n    admin.onRegister(user);\n    return ResponseEntity.status(201).body(user);\n}',explain:[{at:'// service/AdminService.java',to:'import org.springframework.stereotype.Service;',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。'},{at:'@Service',to:'public class AdminService implements ApplicationRunner {',text:'实现 ApplicationRunner 接口的 Bean，Spring Boot 启动完成后会自动调用它的 run 方法（第 6 关导入题目的 DataImporter 也是这样）。'},{at:'private static final Pattern CATEGORY',text:'科目名的规则：1 到 20 个小写字母、数字或横线（后面用 matches，要求整个字符串都符合）。'},{at:'private final AdminRepository repo;',to:'private final List<String> admins;',text:'数据访问和管理员名单。'},{at:'public AdminService(',to:'this.admins = Arrays.stream(',text:'@Value("${ADMIN_USERNAMES:}") 读取同名的环境变量，冒号后面是没设置时的默认值（空字符串）。按逗号拆开、去掉空格、去掉空的，得到名单。'},{at:'// 服务启动完成后',to:'repo.migrateRoles(admins);',text:'启动时迁移一次。'},{at:'// 注册成功后调用',to:'repo.setRole(user.id(), "admin");',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'private static StudyService.StudyException error(',to:'return new StudyService.StudyException(status, message);',text:'和第 15 关一样，借用第 10 关带状态码的业务异常，全局错误处理会把它变成 {"error": …}。'},{at:'public void requireAdmin(User user) {',to:'}',text:'判断管理员，要你补全。'},{at:'public Question clean(',to:'return null;',text:'校验题目，要你补全。'},{at:'public Question create(Question q) {',to:'return null;',text:'新增，要你补全。'},{at:'public Question update(Question q) {',to:'return null;',text:'修改，要你补全。'},{at:'public void delete(int id) {',to:'}',text:'删除，要你补全。'},{at:'// controller/AdminController.java',to:'import org.springframework.web.bind.annotation.*;',text:'三个管理接口，已经给出，读懂就行。'},{at:'@RestController',to:'private static final Logger log',text:'所有接口都在 /api/admin 下面；log 用来记审计日志。'},{at:'public record QuestionBody(',text:'请求正文的格式。难度用 Integer 而不是 int：没传时是 null，交给 clean 判断为不合格。'},{at:'private final AuthService auth;',to:'this.admin = admin;',text:'注入认证服务和管理服务。'},{at:'// 先认人',to:'return user;',text:'每个管理接口先调用它：currentUser 没登录时抛出 401，requireAdmin 不是管理员时抛出 403。'},{at:'@PostMapping("/questions")',to:'return ResponseEntity.status(201).body(q);',text:'新增：检查合格后保存，返回 201 和带编号的新题目，再记一行日志：谁做了什么（简单的审计）。'},{at:'@PutMapping("/questions/{id}")',to:'return q;',text:'修改：编号来自路径，没有这道题 404。'},{at:'@DeleteMapping("/questions/{id}")',to:'return ResponseEntity.noContent().build();',text:'删除：成功返回 204，没有正文。'},{at:'// controller/AuthController.java',to:'return ResponseEntity.status(201).body(user);',text:'注册成功后调用 onRegister，名单里的用户名自动成为管理员。'}],solution:{code:'// service/AdminService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.repository.AdminRepository;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.regex.Pattern;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class AdminService implements ApplicationRunner {\n\n    private static final Pattern CATEGORY = Pattern.compile("[a-z0-9-]{1,20}");\n\n    private final AdminRepository repo;\n    private final List<String> admins;\n\n    public AdminService(AdminRepository repo, @Value("${ADMIN_USERNAMES:}") String adminNames) {\n        this.repo = repo;\n        this.admins = Arrays.stream(adminNames.split(",")).map(String::strip).filter(s -> !s.isEmpty()).toList();\n    }\n\n    // 服务启动完成后 Spring Boot 自动调用：迁移角色列，设置名单里已经注册的管理员\n    @Override\n    public void run(ApplicationArguments args) {\n        repo.migrateRoles(admins);\n    }\n\n    // 注册成功后调用：名单里的用户名自动成为管理员\n    public void onRegister(User user) {\n        if (admins.contains(user.username())) {\n            repo.setRole(user.id(), "admin");\n        }\n    }\n\n    private static StudyService.StudyException error(int status, String message) {\n        return new StudyService.StudyException(status, message);\n    }\n\n    // 不是管理员时抛出 403\n    public void requireAdmin(User user) {\n        if (!"admin".equals(repo.role(user.id()))) {\n            throw error(403, "需要管理员权限");\n        }\n    }\n\n    // 去掉首尾空格并检查题目是否合格\n    public Question clean(int id, String category, String title, String answer, Integer difficulty) {\n        String c = category == null ? "" : category.strip();\n        String t = title == null ? "" : title.strip();\n        String a = answer == null ? "" : answer.strip();\n        int titleLen = t.codePointCount(0, t.length());\n        int answerLen = a.codePointCount(0, a.length());\n        if (!CATEGORY.matcher(c).matches() || titleLen < 1 || titleLen > 200 || answerLen < 1 || answerLen > 2000\n                || difficulty == null || difficulty < 1 || difficulty > 3) {\n            throw error(400, "科目要 1–20 个小写字母、数字或横线，题目 1–200 字，答案 1–2000 字，难度 1–3");\n        }\n        return new Question(id, c, t, a, difficulty);\n    }\n\n    public Question create(Question q) {\n        return repo.createQuestion(q);\n    }\n\n    public Question update(Question q) {\n        if (!repo.updateQuestion(q)) {\n            throw error(404, "题目不存在");\n        }\n        return q;\n    }\n\n    public void delete(int id) {\n        if (!repo.deleteQuestion(id)) {\n            throw error(404, "题目不存在");\n        }\n    }\n}\n\n// controller/AdminController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.service.AdminService;\nimport com.example.zixishi.service.AuthService;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api/admin")\npublic class AdminController {\n\n    private static final Logger log = LoggerFactory.getLogger(AdminController.class);\n\n    public record QuestionBody(String category, String title, String answer, Integer difficulty) {}\n\n    private final AuthService auth;\n    private final AdminService admin;\n\n    public AdminController(AuthService auth, AdminService admin) {\n        this.auth = auth;\n        this.admin = admin;\n    }\n\n    // 先认人（没登录 401），再看角色（不是管理员 403）\n    private User requireAdmin(String token) {\n        User user = auth.currentUser(token);\n        admin.requireAdmin(user);\n        return user;\n    }\n\n    @PostMapping("/questions")\n    public ResponseEntity<Question> create(@CookieValue(name = "session", required = false) String token,\n                                           @RequestBody QuestionBody body) {\n        User user = requireAdmin(token);\n        Question q = admin.create(admin.clean(0, body.category(), body.title(), body.answer(), body.difficulty()));\n        log.info("管理员 {} 新增了第 {} 题", user.username(), q.id());\n        return ResponseEntity.status(201).body(q);\n    }\n\n    @PutMapping("/questions/{id}")\n    public Question update(@CookieValue(name = "session", required = false) String token,\n                           @PathVariable int id, @RequestBody QuestionBody body) {\n        User user = requireAdmin(token);\n        Question q = admin.update(admin.clean(id, body.category(), body.title(), body.answer(), body.difficulty()));\n        log.info("管理员 {} 修改了第 {} 题", user.username(), id);\n        return q;\n    }\n\n    @DeleteMapping("/questions/{id}")\n    public ResponseEntity<Void> delete(@CookieValue(name = "session", required = false) String token,\n                                       @PathVariable int id) {\n        User user = requireAdmin(token);\n        admin.delete(id);\n        log.info("管理员 {} 删除了第 {} 题", user.username(), id);\n        return ResponseEntity.noContent().build();\n    }\n}\n\n// controller/AuthController.java：注入 AdminService（加字段和构造函数参数），注册方法改成\n@PostMapping("/register")\npublic ResponseEntity<User> register(@RequestBody Credentials body) {\n    User user = auth.register(body.username(), body.password());\n    admin.onRegister(user);\n    return ResponseEntity.status(201).body(user);\n}',explain:[{at:'// service/AdminService.java',to:'import org.springframework.stereotype.Service;',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。'},{at:'@Service',to:'public class AdminService implements ApplicationRunner {',text:'实现 ApplicationRunner 接口的 Bean，Spring Boot 启动完成后会自动调用它的 run 方法（第 6 关导入题目的 DataImporter 也是这样）。'},{at:'private static final Pattern CATEGORY',text:'科目名的规则：1 到 20 个小写字母、数字或横线（后面用 matches，要求整个字符串都符合）。'},{at:'private final AdminRepository repo;',to:'private final List<String> admins;',text:'数据访问和管理员名单。'},{at:'public AdminService(',to:'this.admins = Arrays.stream(',text:'@Value("${ADMIN_USERNAMES:}") 读取同名的环境变量，冒号后面是没设置时的默认值（空字符串）。按逗号拆开、去掉空格、去掉空的，得到名单。'},{at:'// 服务启动完成后',to:'repo.migrateRoles(admins);',text:'启动时迁移一次。'},{at:'// 注册成功后调用',to:'repo.setRole(user.id(), "admin");',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'private static StudyService.StudyException error(',to:'return new StudyService.StudyException(status, message);',text:'和第 15 关一样，借用第 10 关带状态码的业务异常，全局错误处理会把它变成 {"error": …}。'},{at:'public void requireAdmin(User user) {',to:'throw error(403, "需要管理员权限");',text:'从数据库查出角色，不是 admin 就是没有权限。每次请求都查，改了角色马上生效。"admin".equals(…) 把常量写在前面，角色是 null 也不会出错。'},{at:'public Question clean(',to:'return new Question(id, c, t, a, difficulty);',text:'strip 去掉首尾空格；codePointCount 按字数算（一个汉字算一个）。难度必须有，并且在 1 到 3 之间。'},{at:'public Question create(Question q) {',to:'return repo.createQuestion(q);',text:'保存检查过的题目。'},{at:'public Question update(Question q) {',to:'return q;',text:'修改，没有这道题 404。'},{at:'public void delete(int id) {',to:'throw error(404, "题目不存在");',text:'删除，没有这道题 404。'},{at:'// controller/AdminController.java',to:'import org.springframework.web.bind.annotation.*;',text:'三个管理接口，已经给出，读懂就行。'},{at:'@RestController',to:'private static final Logger log',text:'所有接口都在 /api/admin 下面；log 用来记审计日志。'},{at:'public record QuestionBody(',text:'请求正文的格式。难度用 Integer 而不是 int：没传时是 null，交给 clean 判断为不合格。'},{at:'private final AuthService auth;',to:'this.admin = admin;',text:'注入认证服务和管理服务。'},{at:'// 先认人',to:'return user;',text:'每个管理接口先调用它：currentUser 没登录时抛出 401，requireAdmin 不是管理员时抛出 403。'},{at:'@PostMapping("/questions")',to:'return ResponseEntity.status(201).body(q);',text:'新增：检查合格后保存，返回 201 和带编号的新题目，再记一行日志：谁做了什么（简单的审计）。'},{at:'@PutMapping("/questions/{id}")',to:'return q;',text:'修改：编号来自路径，没有这道题 404。'},{at:'@DeleteMapping("/questions/{id}")',to:'return ResponseEntity.noContent().build();',text:'删除：成功返回 204，没有正文。'},{at:'// controller/AuthController.java',to:'return ResponseEntity.status(201).body(user);',text:'注册成功后调用 onRegister，名单里的用户名自动成为管理员。'}]}},node:{practice:{steps:['新建 src/services/admin.js（代码第一部分），补完 TODO。','新建 src/routes/admin.js（已经给出），按最后的注释修改 app.js 和 src/routes/auth.js。','设置 ADMIN_USERNAMES=你的用户名 重启，登录后用 curl 或页面新增一道题。'],expect:'POST /api/admin/questions {"category":"go","title":"…","answer":"…","difficulty":1}\n→ 201 {"id":25,"category":"go","title":"…","answer":"…","difficulty":1}'},code:'// src/services/admin.js\nconst adminDb = require("../db/admin");\n\nclass AdminError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst ADMINS = (process.env.ADMIN_USERNAMES || "").split(",").map((s) => s.trim()).filter(Boolean);\nconst CATEGORY = /^[a-z0-9-]{1,20}$/;\n\n// 服务启动时调用一次：迁移角色列，设置名单里已经注册的管理员\nfunction migrate() {\n  adminDb.migrateRoles(ADMINS);\n}\n\n// 注册成功后调用：名单里的用户名自动成为管理员\nfunction onRegister(user) {\n  if (ADMINS.includes(user.username)) adminDb.setRole(user.id, "admin");\n}\n\n// 不是管理员时抛出 AdminError(403, "需要管理员权限")\nfunction requireAdmin(user) {\n  // TODO 1：用 adminDb.getRole 查出角色，不是 "admin" 就抛出 403\n}\n\n// 去掉首尾空格并检查题目是否合格，返回 { category, title, answer, difficulty }\nfunction clean(body) {\n  // TODO 2：category、title、answer 转成字符串并去掉首尾空格；科目要匹配 CATEGORY，题目 1–200 字、答案 1–2000 字\n  //         （用 [...文字].length 数字数），难度是 1–3 的整数；不合格抛出 AdminError(400, …)\n}\n\nfunction create(body) {\n  // TODO 3：clean 之后 adminDb.createQuestion\n}\n\nfunction update(id, body) {\n  // TODO 4：clean 之后 adminDb.updateQuestion，返回 false 时抛出 404 “题目不存在”；返回 { id, ...题目 }\n}\n\nfunction remove(id) {\n  // TODO 5：adminDb.deleteQuestion 返回 false 时抛出 404 “题目不存在”\n}\n\nmodule.exports = { AdminError, migrate, onRegister, requireAdmin, create, update, remove };\n\n// src/routes/admin.js\nconst express = require("express");\nconst admin = require("../services/admin");\nconst { requireUser } = require("../middleware");\n\nconst router = express.Router();\n\n// 先认人（requireUser：没登录 401），再看角色（不是管理员 403）\nfunction onlyAdmin(req, res, next) {\n  try {\n    admin.requireAdmin(req.user);\n    next();\n  } catch (err) {\n    res.status(err.status).json({ error: err.message });\n  }\n}\n\nfunction handle(status, fn) {\n  return (req, res, next) => {\n    try {\n      const result = fn(req);\n      if (status === 204) return res.status(204).end();\n      res.status(status).json(result);\n    } catch (err) {\n      if (err instanceof admin.AdminError) return res.status(err.status).json({ error: err.message });\n      next(err);\n    }\n  };\n}\n\nconst log = (req, action, id) => console.log(`管理员 ${req.user.username} ${action}了第 ${id} 题`);\n\nrouter.post("/questions", requireUser, onlyAdmin, handle(201, (req) => {\n  const q = admin.create(req.body);\n  log(req, "新增", q.id);\n  return q;\n}));\nrouter.put("/questions/:id", requireUser, onlyAdmin, handle(200, (req) => {\n  const q = admin.update(Number(req.params.id), req.body);\n  log(req, "修改", q.id);\n  return q;\n}));\nrouter.delete("/questions/:id", requireUser, onlyAdmin, handle(204, (req) => {\n  admin.remove(Number(req.params.id));\n  log(req, "删除", req.params.id);\n}));\n\nmodule.exports = router;\n\n// app.js：在 app.listen 前面调用 require("./src/services/admin").migrate()，\n// 在 app.use("/api", notFound) 前面挂上\napp.use("/api/admin", require("./src/routes/admin"));\n\n// src/routes/auth.js：注册路由里，拿到 auth.register 的结果后、返回之前加上（顶部导入 admin 服务）\nrequire("../services/admin").onRegister(user);',explain:[{at:'// src/services/admin.js',to:'const adminDb = require("../db/admin");',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。'},{at:'class AdminError extends Error {',to:'this.status = status;',text:'业务错误带上状态码：403、400、404。'},{at:'const ADMINS =',to:'const CATEGORY =',text:'管理员名单来自环境变量 ADMIN_USERNAMES，按逗号拆开、去掉空格、去掉空的。科目名的规则：1 到 20 个小写字母、数字或横线。'},{at:'function migrate() {',to:'adminDb.migrateRoles(ADMINS);',text:'服务启动时调用一次。'},{at:'function onRegister(user) {',to:'if (ADMINS.includes(user.username))',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'function requireAdmin(user) {',text:'判断管理员，要你补全。'},{at:'function clean(body) {',text:'校验题目，要你补全。'},{at:'function create(body) {',text:'新增，要你补全。'},{at:'function update(id, body) {',text:'修改，要你补全。'},{at:'function remove(id) {',text:'删除，要你补全。'},{at:'module.exports = { AdminError, migrate,',text:'导出。'},{at:'// src/routes/admin.js',to:'const router = express.Router();',text:'三个管理接口，已经给出，读懂就行。'},{at:'function onlyAdmin(req, res, next) {',to:'res.status(err.status).json({ error: err.message });',text:'“要求管理员”的中间件，挂在 requireUser 后面：先认人，再看角色。'},{at:'function handle(status, fn) {',to:'next(err);',text:'包装函数：成功时按指定的状态码返回，204 没有正文。'},{at:'const log =',text:'记一行日志：谁做了什么（简单的审计）。'},{at:'router.post("/questions",',to:'module.exports = router;',text:'新增 201、修改 200、删除 204。每个路由都先经过 requireUser 和 onlyAdmin。'},{at:'app.use("/api/admin", require("./src/routes/admin"));',text:'挂在 /api/admin 下面，要在 notFound 前面。'},{at:'require("../services/admin").onRegister(user);',text:'注册成功后调用，名单里的用户名自动成为管理员。'}],solution:{code:'// src/services/admin.js\nconst adminDb = require("../db/admin");\n\nclass AdminError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst ADMINS = (process.env.ADMIN_USERNAMES || "").split(",").map((s) => s.trim()).filter(Boolean);\nconst CATEGORY = /^[a-z0-9-]{1,20}$/;\n\n// 服务启动时调用一次：迁移角色列，设置名单里已经注册的管理员\nfunction migrate() {\n  adminDb.migrateRoles(ADMINS);\n}\n\n// 注册成功后调用：名单里的用户名自动成为管理员\nfunction onRegister(user) {\n  if (ADMINS.includes(user.username)) adminDb.setRole(user.id, "admin");\n}\n\nfunction requireAdmin(user) {\n  if (adminDb.getRole(user.id) !== "admin") throw new AdminError(403, "需要管理员权限");\n}\n\n// 去掉首尾空格并检查题目是否合格\nfunction clean(body) {\n  const q = {\n    category: String(body?.category ?? "").trim(),\n    title: String(body?.title ?? "").trim(),\n    answer: String(body?.answer ?? "").trim(),\n    difficulty: body?.difficulty,\n  };\n  const titleLen = [...q.title].length;\n  const answerLen = [...q.answer].length;\n  if (!CATEGORY.test(q.category) || titleLen < 1 || titleLen > 200 || answerLen < 1 || answerLen > 2000\n      || !Number.isInteger(q.difficulty) || q.difficulty < 1 || q.difficulty > 3) {\n    throw new AdminError(400, "科目要 1–20 个小写字母、数字或横线，题目 1–200 字，答案 1–2000 字，难度 1–3");\n  }\n  return q;\n}\n\nfunction create(body) {\n  return adminDb.createQuestion(clean(body));\n}\n\nfunction update(id, body) {\n  const q = clean(body);\n  if (!adminDb.updateQuestion(id, q)) throw new AdminError(404, "题目不存在");\n  return { id, ...q };\n}\n\nfunction remove(id) {\n  if (!adminDb.deleteQuestion(id)) throw new AdminError(404, "题目不存在");\n}\n\nmodule.exports = { AdminError, migrate, onRegister, requireAdmin, create, update, remove };\n\n// src/routes/admin.js\nconst express = require("express");\nconst admin = require("../services/admin");\nconst { requireUser } = require("../middleware");\n\nconst router = express.Router();\n\n// 先认人（requireUser：没登录 401），再看角色（不是管理员 403）\nfunction onlyAdmin(req, res, next) {\n  try {\n    admin.requireAdmin(req.user);\n    next();\n  } catch (err) {\n    res.status(err.status).json({ error: err.message });\n  }\n}\n\nfunction handle(status, fn) {\n  return (req, res, next) => {\n    try {\n      const result = fn(req);\n      if (status === 204) return res.status(204).end();\n      res.status(status).json(result);\n    } catch (err) {\n      if (err instanceof admin.AdminError) return res.status(err.status).json({ error: err.message });\n      next(err);\n    }\n  };\n}\n\nconst log = (req, action, id) => console.log(`管理员 ${req.user.username} ${action}了第 ${id} 题`);\n\nrouter.post("/questions", requireUser, onlyAdmin, handle(201, (req) => {\n  const q = admin.create(req.body);\n  log(req, "新增", q.id);\n  return q;\n}));\nrouter.put("/questions/:id", requireUser, onlyAdmin, handle(200, (req) => {\n  const q = admin.update(Number(req.params.id), req.body);\n  log(req, "修改", q.id);\n  return q;\n}));\nrouter.delete("/questions/:id", requireUser, onlyAdmin, handle(204, (req) => {\n  admin.remove(Number(req.params.id));\n  log(req, "删除", req.params.id);\n}));\n\nmodule.exports = router;\n\n// app.js：在 app.listen 前面调用 require("./src/services/admin").migrate()，\n// 在 app.use("/api", notFound) 前面挂上\napp.use("/api/admin", require("./src/routes/admin"));\n\n// src/routes/auth.js：注册路由里，拿到 auth.register 的结果后、返回之前加上（顶部导入 admin 服务）\nrequire("../services/admin").onRegister(user);',explain:[{at:'// src/services/admin.js',to:'const adminDb = require("../db/admin");',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。'},{at:'class AdminError extends Error {',to:'this.status = status;',text:'业务错误带上状态码：403、400、404。'},{at:'const ADMINS =',to:'const CATEGORY =',text:'管理员名单来自环境变量 ADMIN_USERNAMES，按逗号拆开、去掉空格、去掉空的。科目名的规则：1 到 20 个小写字母、数字或横线。'},{at:'function migrate() {',to:'adminDb.migrateRoles(ADMINS);',text:'服务启动时调用一次。'},{at:'function onRegister(user) {',to:'if (ADMINS.includes(user.username))',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'function requireAdmin(user) {',to:'if (adminDb.getRole(user.id) !== "admin")',text:'从数据库查出角色，不是 admin 就是没有权限。每次请求都查，改了角色马上生效。'},{at:'function clean(body) {',to:'return q;',text:'body?.category ?? "" 让没传、传了 null 都变成空字符串；[...文字].length 按字数算。难度必须是整数。'},{at:'function create(body) {',to:'return adminDb.createQuestion(clean(body));',text:'检查合格再保存。'},{at:'function update(id, body) {',to:'return { id, ...q };',text:'检查合格再修改，没有这道题 404。'},{at:'function remove(id) {',to:'if (!adminDb.deleteQuestion(id))',text:'删除，没有这道题 404。'},{at:'module.exports = { AdminError, migrate,',text:'导出。'},{at:'// src/routes/admin.js',to:'const router = express.Router();',text:'三个管理接口，已经给出，读懂就行。'},{at:'function onlyAdmin(req, res, next) {',to:'res.status(err.status).json({ error: err.message });',text:'“要求管理员”的中间件，挂在 requireUser 后面：先认人，再看角色。'},{at:'function handle(status, fn) {',to:'next(err);',text:'包装函数：成功时按指定的状态码返回，204 没有正文。'},{at:'const log =',text:'记一行日志：谁做了什么（简单的审计）。'},{at:'router.post("/questions",',to:'module.exports = router;',text:'新增 201、修改 200、删除 204。每个路由都先经过 requireUser 和 onlyAdmin。'},{at:'app.use("/api/admin", require("./src/routes/admin"));',text:'挂在 /api/admin 下面，要在 notFound 前面。'},{at:'require("../services/admin").onRegister(user);',text:'注册成功后调用，名单里的用户名自动成为管理员。'}]}},python:{practice:{steps:['新建 app/services/admin.py（代码第一部分），补完 TODO。','新建 app/routers/admin.py（已经给出），按最后的注释修改 main.py 和 app/routers/auth.py。','设置 ADMIN_USERNAMES=你的用户名 重启，登录后用 curl 或页面新增一道题。'],expect:'POST /api/admin/questions {"category":"go","title":"…","answer":"…","difficulty":1}\n→ 201 {"id":25,"category":"go","title":"…","answer":"…","difficulty":1}'},code:'# app/services/admin.py\nimport os\nimport re\n\nfrom app import admin_db\n\n\nclass AdminError(Exception):\n    def __init__(self, status, message):\n        self.status = status\n        self.message = message\n\n\nADMINS = [s.strip() for s in os.getenv("ADMIN_USERNAMES", "").split(",") if s.strip()]\nCATEGORY = re.compile(r"[a-z0-9-]{1,20}")\n\n\ndef migrate():\n    """服务启动时调用一次：迁移角色列，设置名单里已经注册的管理员"""\n    admin_db.migrate_roles(ADMINS)\n\n\ndef on_register(user):\n    """注册成功后调用：名单里的用户名自动成为管理员"""\n    if user["username"] in ADMINS:\n        admin_db.set_role(user["id"], "admin")\n\n\ndef require_admin(user):\n    """不是管理员时抛出 AdminError(403, "需要管理员权限")"""\n    # TODO 1：用 admin_db.get_role 查出角色，不是 "admin" 就抛出 403\n    pass\n\n\ndef clean(category, title, answer, difficulty):\n    """去掉首尾空格并检查题目是否合格，返回 {"category", "title", "answer", "difficulty"}"""\n    # TODO 2：三段文字去掉首尾空格；科目要 CATEGORY.fullmatch，题目 1–200 字、答案 1–2000 字，\n    #         难度是 1、2、3 之一；不合格抛出 AdminError(400, …)\n    pass\n\n\ndef create(q):\n    # TODO 3：admin_db.create_question（q 已经 clean 过）\n    pass\n\n\ndef update(qid, q):\n    # TODO 4：admin_db.update_question 返回 False 时抛出 404 “题目不存在”；返回 {"id": qid, **q}\n    pass\n\n\ndef remove(qid):\n    # TODO 5：admin_db.delete_question 返回 False 时抛出 404 “题目不存在”\n    pass\n\n\n# app/routers/admin.py\nimport logging\n\nfrom fastapi import APIRouter, Depends, Response\nfrom pydantic import BaseModel\n\nfrom app.routers.study import require_user\nfrom app.services import admin\n\nrouter = APIRouter(prefix="/api/admin")\nlog = logging.getLogger("zixishi")\n\n\nclass QuestionBody(BaseModel):\n    category: str\n    title: str\n    answer: str\n    difficulty: int\n\n\ndef require_admin(user=Depends(require_user)):\n    """先认人（require_user：没登录 401），再看角色（不是管理员 403）"""\n    admin.require_admin(user)\n    return user\n\n\ndef cleaned(body):\n    return admin.clean(body.category, body.title, body.answer, body.difficulty)\n\n\n@router.post("/questions", status_code=201)\ndef create(body: QuestionBody, user=Depends(require_admin)):\n    q = admin.create(cleaned(body))\n    log.info("管理员 %s 新增了第 %d 题", user["username"], q["id"])\n    return q\n\n\n@router.put("/questions/{qid}")\ndef update(qid: int, body: QuestionBody, user=Depends(require_admin)):\n    q = admin.update(qid, cleaned(body))\n    log.info("管理员 %s 修改了第 %d 题", user["username"], qid)\n    return q\n\n\n@router.delete("/questions/{qid}", status_code=204)\ndef delete(qid: int, user=Depends(require_admin)):\n    admin.remove(qid)\n    log.info("管理员 %s 删除了第 %d 题", user["username"], qid)\n    return Response(status_code=204)\n\n\n# main.py：顶部导入，和其他 include_router 放在一起，再加一个错误处理\nfrom app.routers import admin as admin_routes\nfrom app.services import admin as admin_service\nfrom app.services.admin import AdminError\n\napp.include_router(admin_routes.router)\n\n\n@app.exception_handler(AdminError)\nasync def admin_error(request: Request, exc: AdminError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)\n\n# main.py：if __name__ == "__main__": 里面，init_db() 的下一行加上\n    admin_service.migrate()\n\n# app/routers/auth.py：注册路由改成（顶部加 from app.services import admin）\n@router.post("/register", status_code=201)\ndef register(body: Credentials):\n    user = auth.register(body.username, body.password)\n    admin.on_register(user)\n    return user',explain:[{at:'# app/services/admin.py',to:'from app import admin_db',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。re 是正则表达式模块。'},{at:'class AdminError(Exception):',to:'self.message = message',text:'业务错误带上状态码：403、400、404。'},{at:'ADMINS =',to:'CATEGORY =',text:'管理员名单来自环境变量 ADMIN_USERNAMES：按逗号拆开、去掉空格、去掉空的。科目名的规则：1 到 20 个小写字母、数字或横线（后面用 fullmatch，要求整个字符串都符合）。'},{at:'def migrate():',to:'admin_db.migrate_roles(ADMINS)',text:'服务启动时调用一次。'},{at:'def on_register(user):',to:'admin_db.set_role(user["id"], "admin")',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'def require_admin(user):',to:'    pass',text:'判断管理员，要你补全。'},{at:'def clean(category, title, answer, difficulty):',to:'    pass',text:'校验题目，要你补全。'},{at:'def create(q):',to:'    pass',text:'新增，要你补全。'},{at:'def update(qid, q):',to:'    pass',text:'修改，要你补全。'},{at:'def remove(qid):',to:'    pass',text:'删除，要你补全。'},{at:'# app/routers/admin.py',to:'log = logging.getLogger("zixishi")',text:'三个管理接口，已经给出，读懂就行。require_user 是第 10 关写的“要求登录”依赖。'},{at:'class QuestionBody(BaseModel):',to:'difficulty: int',text:'请求体的格式：缺字段或者类型不对，FastAPI 会自动拒绝，第 5 关的错误处理把它变成 400。'},{at:'def require_admin(user=Depends(require_user)):',to:'return user',text:'“要求管理员”的依赖：它自己又依赖 require_user，所以先认人，再看角色。'},{at:'def cleaned(body):',to:'return admin.clean(',text:'把请求体交给 clean 检查。'},{at:'@router.post("/questions", status_code=201)',to:'return Response(status_code=204)',text:'新增 201、修改 200、删除 204。每个接口都用 Depends(require_admin)，并记一行日志：谁做了什么（简单的审计）。'},{at:'# main.py：顶部导入',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'注册路由，并把 AdminError 翻译成 JSON 错误响应。'},{at:'# main.py：if __name__',to:'admin_service.migrate()',text:'建好表以后迁移角色列。'},{at:'# app/routers/auth.py',to:'return user',text:'注册成功后调用 on_register，名单里的用户名自动成为管理员。'}],solution:{code:'# app/services/admin.py\nimport os\nimport re\n\nfrom app import admin_db\n\n\nclass AdminError(Exception):\n    def __init__(self, status, message):\n        self.status = status\n        self.message = message\n\n\nADMINS = [s.strip() for s in os.getenv("ADMIN_USERNAMES", "").split(",") if s.strip()]\nCATEGORY = re.compile(r"[a-z0-9-]{1,20}")\n\n\ndef migrate():\n    """服务启动时调用一次：迁移角色列，设置名单里已经注册的管理员"""\n    admin_db.migrate_roles(ADMINS)\n\n\ndef on_register(user):\n    """注册成功后调用：名单里的用户名自动成为管理员"""\n    if user["username"] in ADMINS:\n        admin_db.set_role(user["id"], "admin")\n\n\ndef require_admin(user):\n    if admin_db.get_role(user["id"]) != "admin":\n        raise AdminError(403, "需要管理员权限")\n\n\ndef clean(category, title, answer, difficulty):\n    """去掉首尾空格并检查题目是否合格"""\n    q = {"category": category.strip(), "title": title.strip(), "answer": answer.strip(), "difficulty": difficulty}\n    if (not CATEGORY.fullmatch(q["category"]) or not 1 <= len(q["title"]) <= 200\n            or not 1 <= len(q["answer"]) <= 2000 or difficulty not in (1, 2, 3)):\n        raise AdminError(400, "科目要 1–20 个小写字母、数字或横线，题目 1–200 字，答案 1–2000 字，难度 1–3")\n    return q\n\n\ndef create(q):\n    return admin_db.create_question(q)\n\n\ndef update(qid, q):\n    if not admin_db.update_question(qid, q):\n        raise AdminError(404, "题目不存在")\n    return {"id": qid, **q}\n\n\ndef remove(qid):\n    if not admin_db.delete_question(qid):\n        raise AdminError(404, "题目不存在")\n\n\n# app/routers/admin.py\nimport logging\n\nfrom fastapi import APIRouter, Depends, Response\nfrom pydantic import BaseModel\n\nfrom app.routers.study import require_user\nfrom app.services import admin\n\nrouter = APIRouter(prefix="/api/admin")\nlog = logging.getLogger("zixishi")\n\n\nclass QuestionBody(BaseModel):\n    category: str\n    title: str\n    answer: str\n    difficulty: int\n\n\ndef require_admin(user=Depends(require_user)):\n    """先认人（require_user：没登录 401），再看角色（不是管理员 403）"""\n    admin.require_admin(user)\n    return user\n\n\ndef cleaned(body):\n    return admin.clean(body.category, body.title, body.answer, body.difficulty)\n\n\n@router.post("/questions", status_code=201)\ndef create(body: QuestionBody, user=Depends(require_admin)):\n    q = admin.create(cleaned(body))\n    log.info("管理员 %s 新增了第 %d 题", user["username"], q["id"])\n    return q\n\n\n@router.put("/questions/{qid}")\ndef update(qid: int, body: QuestionBody, user=Depends(require_admin)):\n    q = admin.update(qid, cleaned(body))\n    log.info("管理员 %s 修改了第 %d 题", user["username"], qid)\n    return q\n\n\n@router.delete("/questions/{qid}", status_code=204)\ndef delete(qid: int, user=Depends(require_admin)):\n    admin.remove(qid)\n    log.info("管理员 %s 删除了第 %d 题", user["username"], qid)\n    return Response(status_code=204)\n\n\n# main.py：顶部导入，和其他 include_router 放在一起，再加一个错误处理\nfrom app.routers import admin as admin_routes\nfrom app.services import admin as admin_service\nfrom app.services.admin import AdminError\n\napp.include_router(admin_routes.router)\n\n\n@app.exception_handler(AdminError)\nasync def admin_error(request: Request, exc: AdminError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)\n\n# main.py：if __name__ == "__main__": 里面，init_db() 的下一行加上\n    admin_service.migrate()\n\n# app/routers/auth.py：注册路由改成（顶部加 from app.services import admin）\n@router.post("/register", status_code=201)\ndef register(body: Credentials):\n    user = auth.register(body.username, body.password)\n    admin.on_register(user)\n    return user',explain:[{at:'# app/services/admin.py',to:'from app import admin_db',text:'管理后台的业务规则：谁是管理员、题目怎样才合格。re 是正则表达式模块。'},{at:'class AdminError(Exception):',to:'self.message = message',text:'业务错误带上状态码：403、400、404。'},{at:'ADMINS =',to:'CATEGORY =',text:'管理员名单来自环境变量 ADMIN_USERNAMES：按逗号拆开、去掉空格、去掉空的。科目名的规则：1 到 20 个小写字母、数字或横线（后面用 fullmatch，要求整个字符串都符合）。'},{at:'def migrate():',to:'admin_db.migrate_roles(ADMINS)',text:'服务启动时调用一次。'},{at:'def on_register(user):',to:'admin_db.set_role(user["id"], "admin")',text:'注册成功后调用：名单里的用户名设成管理员。'},{at:'def require_admin(user):',to:'raise AdminError(403, "需要管理员权限")',text:'从数据库查出角色，不是 admin 就是没有权限。每次请求都查，改了角色马上生效。'},{at:'def clean(category, title, answer, difficulty):',to:'return q',text:'strip 去掉首尾空格；len 按字数算；1 <= x <= 200 是 Python 的连续比较。难度必须是 1、2、3 之一。'},{at:'def create(q):',to:'return admin_db.create_question(q)',text:'保存检查过的题目。'},{at:'def update(qid, q):',to:'return {"id": qid, **q}',text:'修改，没有这道题 404。'},{at:'def remove(qid):',to:'raise AdminError(404, "题目不存在")',text:'删除，没有这道题 404。'},{at:'# app/routers/admin.py',to:'log = logging.getLogger("zixishi")',text:'三个管理接口，已经给出，读懂就行。require_user 是第 10 关写的“要求登录”依赖。'},{at:'class QuestionBody(BaseModel):',to:'difficulty: int',text:'请求体的格式：缺字段或者类型不对，FastAPI 会自动拒绝，第 5 关的错误处理把它变成 400。'},{at:'def require_admin(user=Depends(require_user)):',to:'return user',text:'“要求管理员”的依赖：它自己又依赖 require_user，所以先认人，再看角色。'},{at:'def cleaned(body):',to:'return admin.clean(',text:'把请求体交给 clean 检查。'},{at:'@router.post("/questions", status_code=201)',to:'return Response(status_code=204)',text:'新增 201、修改 200、删除 204。每个接口都用 Depends(require_admin)，并记一行日志：谁做了什么（简单的审计）。'},{at:'# main.py：顶部导入',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'注册路由，并把 AdminError 翻译成 JSON 错误响应。'},{at:'# main.py：if __name__',to:'admin_service.migrate()',text:'建好表以后迁移角色列。'},{at:'# app/routers/auth.py',to:'return user',text:'注册成功后调用 on_register，名单里的用户名自动成为管理员。'}]}}}},
  {title:'任务三：管理页面',body:'做一个只有管理员能用的页面：新增题目、按编号删除题目。修改题目的接口留给你用 curl 试，也可以自己在页面上加。',variants:{html:{body:'原生 HTML：新建 admin.html 和 admin.js。',practice:{steps:['新建 admin.html 和 admin.js（和 index.html 放在一起），补完 TODO。','首页加一个“管理题库”链接，指向 admin.html。','用 ADMIN_USERNAMES 里的账号登录，打开管理页面新增一道题，再到题库里找到它；然后按编号删掉。换一个普通账号打开，应该看到“需要管理员权限”。'],expect:'管理题库\n新增题目  科目 [go] 难度 [2]  题目 [……]  参考答案 [……]  [新增]\n删除题目  题目编号 [25]  [删除]\n已新增第 25 题'},code:'<!-- admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="index.html">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  <h2>新增题目</h2>\n  <form id="create">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form id="remove">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  <p id="message"></p>\n  <script src="admin.js"></script>\n</body>\n</html>\n\n// admin.js\nconst message = document.getElementById("message");\n\n// 发请求的小工具：没登录跳到登录页；失败时把后端的 error 抛出来；204 没有正文\nasync function send(method, url, body) {\n  const res = await fetch(url, {\n    method,\n    headers: { "Content-Type": "application/json" },\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n  if (res.status === 401) {\n    location.href = "login.html";\n    throw new Error("请先登录");\n  }\n  const data = res.status === 204 ? null : await res.json();\n  if (!res.ok) throw new Error(data.error);\n  return data;\n}\n\ndocument.getElementById("create").addEventListener("submit", async (event) => {\n  event.preventDefault();\n  // TODO 1：用 new FormData(event.target) 取出四个字段（难度要用 Number 转成数字），\n  //         send("POST", "/api/admin/questions", …)；成功显示“已新增第 n 题”并清空表单（reset），失败显示错误信息\n});\n\ndocument.getElementById("remove").addEventListener("submit", async (event) => {\n  event.preventDefault();\n  // TODO 2：取出编号，send("DELETE", "/api/admin/questions/" + 编号)；成功显示“已删除第 n 题”，失败显示错误信息\n});',explain:[{at:'<!-- admin.html -->',to:'</head>',text:'新建管理页面 admin.html。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h2>新增题目</h2>',to:'</form>',text:'新增题目的表单：科目、难度（下拉框，选项的值就是文字 1、2、3）、题目、参考答案。required 和 maxlength 让浏览器先拦一道，后端照样要检查。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'<p id="message"></p>',to:'</html>',text:'显示结果或错误的段落，最后引入 admin.js。'},{at:'// admin.js',to:'const message =',text:'admin.js 先拿到显示结果的段落。'},{at:'async function send(',to:'return data;',text:'发请求的小工具，和前几关的 postJSON 差不多，多了一个 method 参数；删除成功是 204，没有正文，不能调用 res.json()。'},{at:'document.getElementById("create")',to:'});',text:'提交新增表单，要你补全。event.preventDefault() 阻止浏览器自己提交表单（那样会刷新页面）。'},{at:'document.getElementById("remove")',to:'});',text:'提交删除表单，要你补全。'}],solution:{code:'<!-- admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="index.html">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  <h2>新增题目</h2>\n  <form id="create">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form id="remove">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  <p id="message"></p>\n  <script src="admin.js"></script>\n</body>\n</html>\n\n// admin.js\nconst message = document.getElementById("message");\n\n// 发请求的小工具：没登录跳到登录页；失败时把后端的 error 抛出来；204 没有正文\nasync function send(method, url, body) {\n  const res = await fetch(url, {\n    method,\n    headers: { "Content-Type": "application/json" },\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n  if (res.status === 401) {\n    location.href = "login.html";\n    throw new Error("请先登录");\n  }\n  const data = res.status === 204 ? null : await res.json();\n  if (!res.ok) throw new Error(data.error);\n  return data;\n}\n\ndocument.getElementById("create").addEventListener("submit", async (event) => {\n  event.preventDefault();\n  const form = new FormData(event.target);\n  try {\n    const q = await send("POST", "/api/admin/questions", {\n      category: form.get("category"),\n      title: form.get("title"),\n      answer: form.get("answer"),\n      difficulty: Number(form.get("difficulty")),\n    });\n    message.textContent = `已新增第 ${q.id} 题`;\n    event.target.reset();\n  } catch (err) {\n    message.textContent = err.message;\n  }\n});\n\ndocument.getElementById("remove").addEventListener("submit", async (event) => {\n  event.preventDefault();\n  const id = new FormData(event.target).get("id");\n  try {\n    await send("DELETE", `/api/admin/questions/${id}`);\n    message.textContent = `已删除第 ${id} 题`;\n  } catch (err) {\n    message.textContent = err.message;\n  }\n});',explain:[{at:'<!-- admin.html -->',to:'</head>',text:'新建管理页面 admin.html。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h2>新增题目</h2>',to:'</form>',text:'新增题目的表单：科目、难度（下拉框，选项的值就是文字 1、2、3）、题目、参考答案。required 和 maxlength 让浏览器先拦一道，后端照样要检查。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'<p id="message"></p>',to:'</html>',text:'显示结果或错误的段落，最后引入 admin.js。'},{at:'// admin.js',to:'const message =',text:'admin.js 先拿到显示结果的段落。'},{at:'async function send(',to:'return data;',text:'发请求的小工具，和前几关的 postJSON 差不多，多了一个 method 参数；删除成功是 204，没有正文，不能调用 res.json()。'},{at:'document.getElementById("create")',to:'const form = new FormData(event.target);',text:'阻止表单自己提交，用 FormData 读出表单里的值（按 name 取）。'},{at:'try {',to:'difficulty: Number(form.get("difficulty")),',text:'表单里的值都是字符串，难度要转成数字，后端要求是整数。'},{at:'});',to:'event.target.reset();',text:'成功后显示新题的编号，清空表单。'},{at:'} catch (err) {',to:'});',text:'失败时显示后端给的原因，比如“需要管理员权限”或者校验不通过的提示。'},{at:'document.getElementById("remove")',to:'await send("DELETE", `/api/admin/questions/${id}`);',text:'删除：编号拼进地址，用 DELETE 方法。'},{at:'message.textContent = `已删除第 ${id} 题`;',to:'});',text:'显示结果或错误。'}]}},react:{body:'React：新建 AdminPage.jsx，在 App.jsx 里加上 ?page=admin。',practice:{steps:['新建 src/AdminPage.jsx，补完 TODO。','App.jsx 顶部 import AdminPage，按最后的注释加一行；UserBar 里加一个“管理题库”链接（/?page=admin）。','用 ADMIN_USERNAMES 里的账号登录，打开管理页面新增一道题，再到题库里找到它；然后按编号删掉。换一个普通账号打开，应该看到“需要管理员权限”。'],expect:'管理题库\n新增题目  科目 [go] 难度 [2]  题目 [……]  参考答案 [……]  [新增]\n删除题目  题目编号 [25]  [删除]\n已新增第 25 题'},code:'// AdminPage.jsx\nimport { useState } from "react";\n\nasync function send(method, url, body) {\n  const res = await fetch(url, {\n    method,\n    headers: { "Content-Type": "application/json" },\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n  if (res.status === 401) {\n    window.location.href = "/?page=login";\n    throw new Error("请先登录");\n  }\n  const data = res.status === 204 ? null : await res.json();\n  if (!res.ok) throw new Error(data.error);\n  return data;\n}\n\nconst empty = { category: "", title: "", answer: "", difficulty: "1" };\n\nexport default function AdminPage() {\n  const [form, setForm] = useState(empty);\n  const [removeId, setRemoveId] = useState("");\n  const [message, setMessage] = useState("");\n  const field = (name) => ({ name, value: form[name], onChange: (e) => setForm({ ...form, [name]: e.target.value }) });\n\n  async function create(event) {\n    event.preventDefault();\n    // TODO 1：send("POST", "/api/admin/questions", …)，难度要用 Number 转成数字；\n    //         成功时 setMessage("已新增第 n 题") 并把表单恢复成 empty，失败时显示错误信息\n  }\n\n  async function remove(event) {\n    event.preventDefault();\n    // TODO 2：send("DELETE", "/api/admin/questions/" + removeId)；成功显示“已删除第 n 题”，失败显示错误信息\n  }\n\n  return (\n    <>\n      <p><a href="/">← 返回题库</a></p>\n      <h1>管理题库</h1>\n      <h2>新增题目</h2>\n      <form onSubmit={create}>\n        <p>\n          <label>科目 <input {...field("category")} placeholder="go" required /></label>\n          <label>难度 <select {...field("difficulty")}><option>1</option><option>2</option><option>3</option></select></label>\n        </p>\n        <p><label>题目<br /><input {...field("title")} size={60} maxLength={200} required /></label></p>\n        <p><label>参考答案<br /><textarea {...field("answer")} rows={6} cols={60} maxLength={2000} required /></label></p>\n        <button>新增</button>\n      </form>\n      <h2>删除题目</h2>\n      <form onSubmit={remove}>\n        <label>题目编号 <input type="number" min="1" value={removeId} onChange={(e) => setRemoveId(e.target.value)} required /></label>\n        <button>删除</button>\n      </form>\n      <p>{message}</p>\n    </>\n  );\n}\n\n// App.jsx：和其他页面一样加一行\nif (params.get("page") === "admin") return <AdminPage />;',explain:[{at:'// AdminPage.jsx',to:'import { useState } from "react";',text:'新建管理页面组件。'},{at:'async function send(',to:'return data;',text:'发请求的小工具：没登录跳到登录页；删除成功是 204，没有正文，不能调用 res.json()。'},{at:'const empty =',text:'表单的初始值。'},{at:'export default function AdminPage() {',to:'const [message, setMessage] = useState("");',text:'三个状态：新增表单的内容、要删除的编号、结果提示。'},{at:'const field = (name) =>',text:'小工具：给输入框生成 name、value、onChange 三个属性，输入时更新 form 里对应的字段。{ ...form, [name]: 新值 } 复制一份再改一个字段。'},{at:'async function create(event) {',to:'event.preventDefault();',text:'提交新增表单，要你补全。'},{at:'async function remove(event) {',to:'event.preventDefault();',text:'提交删除表单，要你补全。'},{at:'return (',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h2>新增题目</h2>',to:'</form>',text:'新增表单：{...field("category")} 把 name、value、onChange 一次展开到输入框上。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除表单：只有一个编号。'},{at:'<p>{message}</p>',to:'</>',text:'显示结果或错误。React 会把它当文本显示。'},{at:'// App.jsx',to:'if (params.get("page") === "admin")',text:'地址是 /?page=admin 时显示管理页面（顶部还要 import AdminPage）。'}],solution:{code:'// AdminPage.jsx\nimport { useState } from "react";\n\nasync function send(method, url, body) {\n  const res = await fetch(url, {\n    method,\n    headers: { "Content-Type": "application/json" },\n    body: body === undefined ? undefined : JSON.stringify(body),\n  });\n  if (res.status === 401) {\n    window.location.href = "/?page=login";\n    throw new Error("请先登录");\n  }\n  const data = res.status === 204 ? null : await res.json();\n  if (!res.ok) throw new Error(data.error);\n  return data;\n}\n\nconst empty = { category: "", title: "", answer: "", difficulty: "1" };\n\nexport default function AdminPage() {\n  const [form, setForm] = useState(empty);\n  const [removeId, setRemoveId] = useState("");\n  const [message, setMessage] = useState("");\n  const field = (name) => ({ name, value: form[name], onChange: (e) => setForm({ ...form, [name]: e.target.value }) });\n\n  async function create(event) {\n    event.preventDefault();\n    try {\n      const q = await send("POST", "/api/admin/questions", { ...form, difficulty: Number(form.difficulty) });\n      setMessage(`已新增第 ${q.id} 题`);\n      setForm(empty);\n    } catch (err) {\n      setMessage(err.message);\n    }\n  }\n\n  async function remove(event) {\n    event.preventDefault();\n    try {\n      await send("DELETE", `/api/admin/questions/${removeId}`);\n      setMessage(`已删除第 ${removeId} 题`);\n    } catch (err) {\n      setMessage(err.message);\n    }\n  }\n\n  return (\n    <>\n      <p><a href="/">← 返回题库</a></p>\n      <h1>管理题库</h1>\n      <h2>新增题目</h2>\n      <form onSubmit={create}>\n        <p>\n          <label>科目 <input {...field("category")} placeholder="go" required /></label>\n          <label>难度 <select {...field("difficulty")}><option>1</option><option>2</option><option>3</option></select></label>\n        </p>\n        <p><label>题目<br /><input {...field("title")} size={60} maxLength={200} required /></label></p>\n        <p><label>参考答案<br /><textarea {...field("answer")} rows={6} cols={60} maxLength={2000} required /></label></p>\n        <button>新增</button>\n      </form>\n      <h2>删除题目</h2>\n      <form onSubmit={remove}>\n        <label>题目编号 <input type="number" min="1" value={removeId} onChange={(e) => setRemoveId(e.target.value)} required /></label>\n        <button>删除</button>\n      </form>\n      <p>{message}</p>\n    </>\n  );\n}\n\n// App.jsx：和其他页面一样加一行\nif (params.get("page") === "admin") return <AdminPage />;',explain:[{at:'// AdminPage.jsx',to:'import { useState } from "react";',text:'新建管理页面组件。'},{at:'async function send(',to:'return data;',text:'发请求的小工具：没登录跳到登录页；删除成功是 204，没有正文，不能调用 res.json()。'},{at:'const empty =',text:'表单的初始值。'},{at:'export default function AdminPage() {',to:'const [message, setMessage] = useState("");',text:'三个状态：新增表单的内容、要删除的编号、结果提示。'},{at:'const field = (name) =>',text:'小工具：给输入框生成 name、value、onChange 三个属性，输入时更新 form 里对应的字段。{ ...form, [name]: 新值 } 复制一份再改一个字段。'},{at:'async function create(event) {',to:'setForm(empty);',text:'阻止表单自己提交；难度从字符串转成数字；成功后显示编号，清空表单。'},{at:'} catch (err) {',to:'setMessage(err.message);',text:'失败时显示后端给的原因。'},{at:'async function remove(event) {',to:'setMessage(`已删除第 ${removeId} 题`);',text:'删除：编号拼进地址，用 DELETE 方法。'},{at:'} catch (err) {',to:'setMessage(err.message);',text:'失败时显示错误。'},{at:'return (',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h2>新增题目</h2>',to:'</form>',text:'新增表单：{...field("category")} 把 name、value、onChange 一次展开到输入框上。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除表单：只有一个编号。'},{at:'<p>{message}</p>',to:'</>',text:'显示结果或错误。React 会把它当文本显示。'},{at:'// App.jsx',to:'if (params.get("page") === "admin")',text:'地址是 /?page=admin 时显示管理页面（顶部还要 import AdminPage）。'}]}},'template-go':{body:'模板渲染的做法：新增管理页面 /admin，上面两个表单：新增题目提交到 POST /admin/questions，删除题目提交到 POST /admin/questions/delete。后端调用和 JSON 接口同一个管理服务，再渲染同一个页面，把结果（“已新增第 n 题”）或错误提示显示出来。\n没登录时重定向到登录页；登录了但不是管理员，返回 403，页面上只显示“需要管理员权限”。\n还有一处要补：登录页的“注册”也要调用 OnRegister，否则用名单里的用户名在页面上注册，不会成为管理员。',practice:{steps:['新建 internal/handler/pages_admin.go（代码第一部分），补完 TODO；按中间的注释修改 handler.go 和 pages_auth.go。','新建 web/templates/admin.html（代码最后一部分），首页加一个“管理题库”链接指向 /admin。','用 ADMIN_USERNAMES 里的账号登录，打开 /admin 新增一道题，到题库里找到它，再按编号删掉。换一个普通账号打开 /admin，应该看到“需要管理员权限”。'],expect:'管理题库\n已新增第 25 题\n新增题目  科目 [go] 难度 [1▾]  题目 [……]  参考答案 [……]  [新增]\n删除题目  题目编号 [  ]  [删除]'},code:'// internal/handler/pages_admin.go\npackage handler\n\nimport (\n    "errors"\n    "fmt"\n    "log"\n    "net/http"\n    "strconv"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// adminPageUser 页面版的“要求管理员”：没登录重定向到登录页，不是管理员显示 403 页面。\nfunc (h *Handler) adminPageUser(w http.ResponseWriter, r *http.Request) (store.User, bool) {\n    u, ok := h.pageUser(w, r)\n    if !ok {\n        return u, false\n    }\n    if err := h.admin.RequireAdmin(u); err != nil {\n        if errors.Is(err, service.ErrForbidden) {\n            h.render(w, http.StatusForbidden, "admin.html", map[string]any{"Error": err.Error()})\n        } else {\n            h.serverError(w, err)\n        }\n        return u, false\n    }\n    return u, true\n}\n\n// adminResult 渲染管理页面：没有出错时显示 message，出错时按错误类型显示提示和状态码。\nfunc (h *Handler) adminResult(w http.ResponseWriter, err error, message string) {\n    switch {\n    case err == nil:\n        h.render(w, http.StatusOK, "admin.html", map[string]any{"IsAdmin": true, "Message": message})\n    case errors.Is(err, service.ErrInvalidQuestion):\n        h.render(w, http.StatusBadRequest, "admin.html", map[string]any{"IsAdmin": true, "Error": err.Error()})\n    case errors.Is(err, store.ErrNotFound):\n        h.render(w, http.StatusNotFound, "admin.html", map[string]any{"IsAdmin": true, "Error": "题目不存在"})\n    default:\n        h.serverError(w, err)\n    }\n}\n\nfunc (h *Handler) adminPage(w http.ResponseWriter, r *http.Request) {\n    if _, ok := h.adminPageUser(w, r); ok {\n        h.adminResult(w, nil, "")\n    }\n}\n\nfunc (h *Handler) adminCreateForm(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.adminPageUser(w, r)\n    if !ok {\n        return\n    }\n    // TODO 1：用 r.FormValue 取出四个字段（难度用 strconv.Atoi 转成整数），组成 store.Question 交给 h.admin.Create；\n    //         成功时记一行日志；最后 h.adminResult(w, err, "已新增第 n 题")\n    _ = u\n}\n\nfunc (h *Handler) adminDeleteForm(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.adminPageUser(w, r)\n    if !ok {\n        return\n    }\n    // TODO 2：取出 id 转成整数（转不了就当作 store.ErrNotFound），交给 h.admin.Delete；\n    //         成功时记一行日志；最后 h.adminResult(w, err, "已删除第 n 题")\n    _ = u\n}\n\n// handler.go 的 Routes 里注册\nmux.HandleFunc("GET /admin", h.adminPage)\nmux.HandleFunc("POST /admin/questions", h.adminCreateForm)\nmux.HandleFunc("POST /admin/questions/delete", h.adminDeleteForm)\n\n// pages_auth.go 的 loginForm：注册那一段改成\nif r.FormValue("action") == "register" {\n    u, err := h.auth.Register(username, password)\n    if err == nil {\n        err = h.admin.OnRegister(u)\n    }\n    if err != nil {\n        h.loginFailed(w, err)\n        return\n    }\n}\n\n<!-- web/templates/admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  {{with .Message}}<p>{{.}}</p>{{end}}\n  {{with .Error}}<p style="color: red">{{.}}</p>{{end}}\n  {{if .IsAdmin}}\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  {{end}}\n</body>\n</html>',explain:[{at:'// internal/handler/pages_admin.go',to:'"zixishi/internal/store"',text:'管理页面的处理函数，放在一个新文件里。'},{at:'// adminPageUser',to:'u, ok := h.pageUser(w, r)',text:'先用第 10 关的 pageUser 认人：没登录时它已经重定向到登录页了。'},{at:'if !ok {',to:'return u, true',text:'再看角色：不是管理员，渲染同一个页面，状态码 403，只显示错误（没有 IsAdmin，表单不显示）。第二个返回值告诉调用方能不能继续。'},{at:'// adminResult',to:'h.serverError(w, err)',text:'统一渲染结果：成功 200 显示提示；题目不合格 400；没有这道题 404；其他错误 500。'},{at:'func (h *Handler) adminPage(',to:'h.adminResult(w, nil, "")',text:'打开管理页面：是管理员就显示空表单。'},{at:'func (h *Handler) adminCreateForm(',to:'_ = u',text:'提交新增表单，要你补全。前几行已经检查过管理员。_ = u 只是让没用到的变量先能编译，写完就删掉。'},{at:'func (h *Handler) adminDeleteForm(',to:'_ = u',text:'提交删除表单，要你补全。'},{at:'// handler.go 的 Routes 里注册',to:'mux.HandleFunc("POST /admin/questions/delete", h.adminDeleteForm)',text:'三个页面地址。HTML 表单只能发 GET 和 POST，所以删除用 POST 加一个 /delete 结尾的地址。'},{at:'// pages_auth.go 的 loginForm',to:'return',text:'页面上注册成功后也调用 OnRegister，名单里的用户名才会成为管理员。'},{at:'<!-- web/templates/admin.html -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'{{end}}',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}],solution:{code:'// internal/handler/pages_admin.go\npackage handler\n\nimport (\n    "errors"\n    "fmt"\n    "log"\n    "net/http"\n    "strconv"\n\n    "zixishi/internal/service"\n    "zixishi/internal/store"\n)\n\n// adminPageUser 页面版的“要求管理员”：没登录重定向到登录页，不是管理员显示 403 页面。\nfunc (h *Handler) adminPageUser(w http.ResponseWriter, r *http.Request) (store.User, bool) {\n    u, ok := h.pageUser(w, r)\n    if !ok {\n        return u, false\n    }\n    if err := h.admin.RequireAdmin(u); err != nil {\n        if errors.Is(err, service.ErrForbidden) {\n            h.render(w, http.StatusForbidden, "admin.html", map[string]any{"Error": err.Error()})\n        } else {\n            h.serverError(w, err)\n        }\n        return u, false\n    }\n    return u, true\n}\n\n// adminResult 渲染管理页面：没有出错时显示 message，出错时按错误类型显示提示和状态码。\nfunc (h *Handler) adminResult(w http.ResponseWriter, err error, message string) {\n    switch {\n    case err == nil:\n        h.render(w, http.StatusOK, "admin.html", map[string]any{"IsAdmin": true, "Message": message})\n    case errors.Is(err, service.ErrInvalidQuestion):\n        h.render(w, http.StatusBadRequest, "admin.html", map[string]any{"IsAdmin": true, "Error": err.Error()})\n    case errors.Is(err, store.ErrNotFound):\n        h.render(w, http.StatusNotFound, "admin.html", map[string]any{"IsAdmin": true, "Error": "题目不存在"})\n    default:\n        h.serverError(w, err)\n    }\n}\n\nfunc (h *Handler) adminPage(w http.ResponseWriter, r *http.Request) {\n    if _, ok := h.adminPageUser(w, r); ok {\n        h.adminResult(w, nil, "")\n    }\n}\n\nfunc (h *Handler) adminCreateForm(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.adminPageUser(w, r)\n    if !ok {\n        return\n    }\n    difficulty, _ := strconv.Atoi(r.FormValue("difficulty"))\n    q, err := h.admin.Create(store.Question{Category: r.FormValue("category"), Title: r.FormValue("title"),\n        Answer: r.FormValue("answer"), Difficulty: difficulty})\n    if err == nil {\n        log.Printf("管理员 %s 新增了第 %d 题", u.Username, q.ID)\n    }\n    h.adminResult(w, err, fmt.Sprintf("已新增第 %d 题", q.ID))\n}\n\nfunc (h *Handler) adminDeleteForm(w http.ResponseWriter, r *http.Request) {\n    u, ok := h.adminPageUser(w, r)\n    if !ok {\n        return\n    }\n    id, err := strconv.Atoi(r.FormValue("id"))\n    if err != nil {\n        err = store.ErrNotFound\n    } else if err = h.admin.Delete(id); err == nil {\n        log.Printf("管理员 %s 删除了第 %d 题", u.Username, id)\n    }\n    h.adminResult(w, err, fmt.Sprintf("已删除第 %d 题", id))\n}\n\n// handler.go 的 Routes 里注册\nmux.HandleFunc("GET /admin", h.adminPage)\nmux.HandleFunc("POST /admin/questions", h.adminCreateForm)\nmux.HandleFunc("POST /admin/questions/delete", h.adminDeleteForm)\n\n// pages_auth.go 的 loginForm：注册那一段改成\nif r.FormValue("action") == "register" {\n    u, err := h.auth.Register(username, password)\n    if err == nil {\n        err = h.admin.OnRegister(u)\n    }\n    if err != nil {\n        h.loginFailed(w, err)\n        return\n    }\n}\n\n<!-- web/templates/admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  {{with .Message}}<p>{{.}}</p>{{end}}\n  {{with .Error}}<p style="color: red">{{.}}</p>{{end}}\n  {{if .IsAdmin}}\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  {{end}}\n</body>\n</html>',explain:[{at:'// internal/handler/pages_admin.go',to:'"zixishi/internal/store"',text:'管理页面的处理函数，放在一个新文件里。'},{at:'// adminPageUser',to:'u, ok := h.pageUser(w, r)',text:'先用第 10 关的 pageUser 认人：没登录时它已经重定向到登录页了。'},{at:'if !ok {',to:'return u, true',text:'再看角色：不是管理员，渲染同一个页面，状态码 403，只显示错误（没有 IsAdmin，表单不显示）。第二个返回值告诉调用方能不能继续。'},{at:'// adminResult',to:'h.serverError(w, err)',text:'统一渲染结果：成功 200 显示提示；题目不合格 400；没有这道题 404；其他错误 500。'},{at:'func (h *Handler) adminPage(',to:'h.adminResult(w, nil, "")',text:'打开管理页面：是管理员就显示空表单。'},{at:'func (h *Handler) adminCreateForm(',to:'return',text:'先检查管理员，不通过时 adminPageUser 已经写好了响应，直接返回。'},{at:'difficulty, _ := strconv.Atoi(',to:'Answer: r.FormValue("answer"), Difficulty: difficulty})',text:'表单的值都是字符串，难度转成整数（转不了是 0，交给 Create 判为不合格）。首尾空格由服务里的 clean 去掉。'},{at:'if err == nil {',to:'h.adminResult(w, err, fmt.Sprintf("已新增第 %d 题", q.ID))',text:'成功时记审计日志；adminResult 根据 err 决定显示提示还是错误。'},{at:'func (h *Handler) adminDeleteForm(',to:'return',text:'同样先检查管理员。'},{at:'id, err := strconv.Atoi(r.FormValue("id"))',to:'h.adminResult(w, err, fmt.Sprintf("已删除第 %d 题", id))',text:'编号不是数字时当作“题目不存在”；else if 里先删除，再判断成功没有。'},{at:'// handler.go 的 Routes 里注册',to:'mux.HandleFunc("POST /admin/questions/delete", h.adminDeleteForm)',text:'三个页面地址。HTML 表单只能发 GET 和 POST，所以删除用 POST 加一个 /delete 结尾的地址。'},{at:'// pages_auth.go 的 loginForm',to:'return',text:'页面上注册成功后也调用 OnRegister，名单里的用户名才会成为管理员。'},{at:'<!-- web/templates/admin.html -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'{{end}}',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}]}},'template-node':{body:'模板渲染的做法：新增管理页面 /admin，上面两个表单：新增题目提交到 POST /admin/questions，删除题目提交到 POST /admin/questions/delete。后端调用和 JSON 接口同一个管理服务，再渲染同一个页面，把结果（“已新增第 n 题”）或错误提示显示出来。\n没登录时重定向到登录页；登录了但不是管理员，返回 403，页面上只显示“需要管理员权限”。\n还有一处要补：登录页的“注册”也要调用 OnRegister，否则用名单里的用户名在页面上注册，不会成为管理员。',practice:{steps:['在 app.js 里加上代码第一部分（放在 pageUser 函数后面），补完 TODO；按中间的注释修改登录的路由。','新建 views/admin.ejs（代码最后一部分），首页加一个“管理题库”链接指向 /admin。','用 ADMIN_USERNAMES 里的账号登录，打开 /admin 新增一道题，到题库里找到它，再按编号删掉。换一个普通账号打开 /admin，应该看到“需要管理员权限”。'],expect:'管理题库\n已新增第 25 题\n新增题目  科目 [go] 难度 [1▾]  题目 [……]  参考答案 [……]  [新增]\n删除题目  题目编号 [  ]  [删除]'},code:'// app.js：管理页面（放在 pageUser 函数后面）\nconst admin = require("./src/services/admin");\n\n// 渲染管理页面：403 时不显示表单\nfunction renderAdmin(res, status, message, error) {\n  res.status(status).render("admin", { isAdmin: status !== 403, message, error });\n}\n\n// pageAdmin：页面版的“要求管理员”，挂在 pageUser 后面\nfunction pageAdmin(req, res, next) {\n  try {\n    admin.requireAdmin(req.user);\n    next();\n  } catch (err) {\n    if (!(err instanceof admin.AdminError)) return next(err);\n    renderAdmin(res, err.status, "", err.message);\n  }\n}\n\napp.get("/admin", pageUser, pageAdmin, (req, res) => renderAdmin(res, 200, "", ""));\n\napp.post("/admin/questions", pageUser, pageAdmin, (req, res, next) => {\n  // TODO 1：admin.create（req.body 里的难度是字符串，要用 Number 转成数字）；成功时记一行日志，\n  //         renderAdmin(res, 200, "已新增第 n 题", "")；AdminError 时 renderAdmin(res, err.status, "", err.message)，其他错误 next(err)\n});\n\napp.post("/admin/questions/delete", pageUser, pageAdmin, (req, res, next) => {\n  // TODO 2：编号用 Number(req.body.id)，admin.remove；成功显示“已删除第 n 题”，出错的处理和上面一样\n});\n\n// app.js 的 POST /login：注册那一行改成\nif (req.body.action === "register") admin.onRegister(auth.register(username, password));\n\n<!-- views/admin.ejs -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  <% if (message) { %><p><%= message %></p><% } %>\n  <% if (error) { %><p style="color: red"><%= error %></p><% } %>\n  <% if (isAdmin) { %>\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  <% } %>\n</body>\n</html>',explain:[{at:'// app.js：管理页面',to:'const admin = require("./src/services/admin");',text:'用上一个任务写的管理服务。'},{at:'// 渲染管理页面',to:'res.status(status).render("admin",',text:'统一渲染管理页面：状态码、提示、错误。403 说明不是管理员，不显示表单。'},{at:'// pageAdmin',to:'renderAdmin(res, err.status, "", err.message);',text:'先经过 pageUser（没登录跳到登录页），再看角色：不是管理员时渲染 403 页面，不再往下走。'},{at:'app.get("/admin"',text:'打开管理页面：两个中间件都通过了，显示空表单。'},{at:'app.post("/admin/questions",',to:'});',text:'提交新增表单，要你补全。'},{at:'app.post("/admin/questions/delete",',to:'});',text:'提交删除表单，要你补全。'},{at:'// app.js 的 POST /login',to:'if (req.body.action === "register") admin.onRegister(',text:'页面上注册成功后也调用 onRegister，名单里的用户名才会成为管理员。admin 要在这之前导入，可以把 require 那一行挪到文件顶部。'},{at:'<!-- views/admin.ejs -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'<% } %>',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}],solution:{code:'// app.js：管理页面（放在 pageUser 函数后面）\nconst admin = require("./src/services/admin");\n\n// 渲染管理页面：403 时不显示表单\nfunction renderAdmin(res, status, message, error) {\n  res.status(status).render("admin", { isAdmin: status !== 403, message, error });\n}\n\n// pageAdmin：页面版的“要求管理员”，挂在 pageUser 后面\nfunction pageAdmin(req, res, next) {\n  try {\n    admin.requireAdmin(req.user);\n    next();\n  } catch (err) {\n    if (!(err instanceof admin.AdminError)) return next(err);\n    renderAdmin(res, err.status, "", err.message);\n  }\n}\n\napp.get("/admin", pageUser, pageAdmin, (req, res) => renderAdmin(res, 200, "", ""));\n\napp.post("/admin/questions", pageUser, pageAdmin, (req, res, next) => {\n  try {\n    const q = admin.create({ ...req.body, difficulty: Number(req.body.difficulty) });\n    console.log(`管理员 ${req.user.username} 新增了第 ${q.id} 题`);\n    renderAdmin(res, 200, `已新增第 ${q.id} 题`, "");\n  } catch (err) {\n    if (!(err instanceof admin.AdminError)) return next(err);\n    renderAdmin(res, err.status, "", err.message);\n  }\n});\n\napp.post("/admin/questions/delete", pageUser, pageAdmin, (req, res, next) => {\n  const id = Number(req.body.id);\n  try {\n    admin.remove(id);\n    console.log(`管理员 ${req.user.username} 删除了第 ${id} 题`);\n    renderAdmin(res, 200, `已删除第 ${id} 题`, "");\n  } catch (err) {\n    if (!(err instanceof admin.AdminError)) return next(err);\n    renderAdmin(res, err.status, "", err.message);\n  }\n});\n\n// app.js 的 POST /login：注册那一行改成\nif (req.body.action === "register") admin.onRegister(auth.register(username, password));\n\n<!-- views/admin.ejs -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  <% if (message) { %><p><%= message %></p><% } %>\n  <% if (error) { %><p style="color: red"><%= error %></p><% } %>\n  <% if (isAdmin) { %>\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  <% } %>\n</body>\n</html>',explain:[{at:'// app.js：管理页面',to:'const admin = require("./src/services/admin");',text:'用上一个任务写的管理服务。'},{at:'// 渲染管理页面',to:'res.status(status).render("admin",',text:'统一渲染管理页面：状态码、提示、错误。403 说明不是管理员，不显示表单。'},{at:'// pageAdmin',to:'renderAdmin(res, err.status, "", err.message);',text:'先经过 pageUser（没登录跳到登录页），再看角色：不是管理员时渲染 403 页面，不再往下走。'},{at:'app.get("/admin"',text:'打开管理页面：两个中间件都通过了，显示空表单。'},{at:'app.post("/admin/questions",',to:'renderAdmin(res, 200, `已新增第 ${q.id} 题`, "");',text:'表单的值都是字符串，难度转成数字再交给管理服务（它会检查和去掉首尾空格）。成功后记审计日志，显示新题的编号。'},{at:'} catch (err) {',to:'});',text:'业务错误（400）显示在页面上；其他错误交给错误处理中间件。'},{at:'app.post("/admin/questions/delete",',to:'renderAdmin(res, 200, `已删除第 ${id} 题`, "");',text:'删除：编号转成数字；没有这道题时 remove 抛出 404。'},{at:'} catch (err) {',to:'});',text:'出错的处理和新增一样。'},{at:'// app.js 的 POST /login',to:'if (req.body.action === "register") admin.onRegister(',text:'页面上注册成功后也调用 onRegister，名单里的用户名才会成为管理员。admin 要在这之前导入，可以把 require 那一行挪到文件顶部。'},{at:'<!-- views/admin.ejs -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'<% } %>',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}]}},'template-python':{body:'模板渲染的做法：新增管理页面 /admin，上面两个表单：新增题目提交到 POST /admin/questions，删除题目提交到 POST /admin/questions/delete。后端调用和 JSON 接口同一个管理服务，再渲染同一个页面，把结果（“已新增第 n 题”）或错误提示显示出来。\n没登录时重定向到登录页；登录了但不是管理员，返回 403，页面上只显示“需要管理员权限”。\n还有一处要补：登录页的“注册”也要调用 OnRegister，否则用名单里的用户名在页面上注册，不会成为管理员。',practice:{steps:['在 main.py 里加上代码第一部分（放在 page_user 函数后面），补完 TODO；按中间的注释修改 login_form。','新建 templates/admin.html（代码最后一部分），首页加一个“管理题库”链接指向 /admin。','用 ADMIN_USERNAMES 里的账号登录，打开 /admin 新增一道题，到题库里找到它，再按编号删掉。换一个普通账号打开 /admin，应该看到“需要管理员权限”。'],expect:'管理题库\n已新增第 25 题\n新增题目  科目 [go] 难度 [1▾]  题目 [……]  参考答案 [……]  [新增]\n删除题目  题目编号 [  ]  [删除]'},code:'# main.py：管理页面（放在 page_user 函数后面；admin_service 和 AdminError 上一个任务已经导入）\ndef render_admin(request, status=200, message="", error=""):\n    """渲染管理页面：403 时不显示表单"""\n    return templates.TemplateResponse(request, "admin.html", {\n        "is_admin": status != 403, "message": message, "error": error,\n    }, status_code=status)\n\n\ndef admin_user(request):\n    """页面版的“要求管理员”：返回 (用户, None)；不通过时返回 (None, 要直接返回的响应)"""\n    user = page_user(request)\n    if user is None:\n        return None, RedirectResponse("/login", status_code=303)\n    try:\n        admin_service.require_admin(user)\n    except AdminError as e:\n        return None, render_admin(request, e.status, error=e.message)\n    return user, None\n\n\n@app.get("/admin", response_class=HTMLResponse)\ndef admin_page(request: Request):\n    user, denied = admin_user(request)\n    if denied:\n        return denied\n    return render_admin(request)\n\n\n@app.post("/admin/questions", response_class=HTMLResponse)\ndef admin_create_form(request: Request, category: str = Form(""), title: str = Form(""),\n                      answer: str = Form(""), difficulty: int = Form(0)):\n    user, denied = admin_user(request)\n    if denied:\n        return denied\n    # TODO 1：clean 检查之后 admin_service.create；AdminError 时 render_admin(request, e.status, error=e.message)；\n    #         成功时记一行日志，render_admin(request, message="已新增第 n 题")\n    return render_admin(request)\n\n\n@app.post("/admin/questions/delete", response_class=HTMLResponse)\ndef admin_delete_form(request: Request, qid: int = Form(0, alias="id")):\n    user, denied = admin_user(request)\n    if denied:\n        return denied\n    # TODO 2：admin_service.remove(qid)，出错的处理和上面一样；成功显示“已删除第 n 题”\n    return render_admin(request)\n\n# main.py 的 login_form：注册那一行改成\nadmin_service.on_register(auth.register(username.strip(), password))\n\n<!-- templates/admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  {% if message %}<p>{{ message }}</p>{% endif %}\n  {% if error %}<p style="color: red">{{ error }}</p>{% endif %}\n  {% if is_admin %}\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  {% endif %}\n</body>\n</html>',explain:[{at:'# main.py：管理页面',to:'}, status_code=status)',text:'统一渲染管理页面：状态码、提示、错误。403 说明不是管理员，不显示表单。'},{at:'def admin_user(request):',to:'return None, RedirectResponse("/login", status_code=303)',text:'先用第 10 关的 page_user 认人，没登录时准备一个跳到登录页的响应。'},{at:'try:',to:'return user, None',text:'再看角色：不是管理员时准备一个 403 页面。Python 函数可以一次返回两个值（元组），调用方用 user, denied = … 分别接住。'},{at:'@app.get("/admin", response_class=HTMLResponse)',to:'return render_admin(request)',text:'打开管理页面：不通过就返回准备好的响应，通过了显示空表单。'},{at:'@app.post("/admin/questions", response_class=HTMLResponse)',to:'return render_admin(request)',text:'提交新增表单，要你补全。参数用 Form 从表单里取，难度 int 会自动转换。'},{at:'@app.post("/admin/questions/delete", response_class=HTMLResponse)',to:'return render_admin(request)',text:'提交删除表单，要你补全。表单字段叫 id，和 Python 自带的 id 函数重名，所以参数叫 qid，用 alias="id" 对上表单的名字。'},{at:'# main.py 的 login_form',to:'admin_service.on_register(auth.register(',text:'页面上注册成功后也调用 on_register，名单里的用户名才会成为管理员。'},{at:'<!-- templates/admin.html -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'{% endif %}',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}],solution:{code:'# main.py：管理页面（放在 page_user 函数后面；admin_service 和 AdminError 上一个任务已经导入）\ndef render_admin(request, status=200, message="", error=""):\n    """渲染管理页面：403 时不显示表单"""\n    return templates.TemplateResponse(request, "admin.html", {\n        "is_admin": status != 403, "message": message, "error": error,\n    }, status_code=status)\n\n\ndef admin_user(request):\n    """页面版的“要求管理员”：返回 (用户, None)；不通过时返回 (None, 要直接返回的响应)"""\n    user = page_user(request)\n    if user is None:\n        return None, RedirectResponse("/login", status_code=303)\n    try:\n        admin_service.require_admin(user)\n    except AdminError as e:\n        return None, render_admin(request, e.status, error=e.message)\n    return user, None\n\n\n@app.get("/admin", response_class=HTMLResponse)\ndef admin_page(request: Request):\n    user, denied = admin_user(request)\n    if denied:\n        return denied\n    return render_admin(request)\n\n\n@app.post("/admin/questions", response_class=HTMLResponse)\ndef admin_create_form(request: Request, category: str = Form(""), title: str = Form(""),\n                      answer: str = Form(""), difficulty: int = Form(0)):\n    user, denied = admin_user(request)\n    if denied:\n        return denied\n    try:\n        q = admin_service.create(admin_service.clean(category, title, answer, difficulty))\n    except AdminError as e:\n        return render_admin(request, e.status, error=e.message)\n    log.info("管理员 %s 新增了第 %d 题", user["username"], q["id"])\n    return render_admin(request, message=f"已新增第 {q[\'id\']} 题")\n\n\n@app.post("/admin/questions/delete", response_class=HTMLResponse)\ndef admin_delete_form(request: Request, qid: int = Form(0, alias="id")):\n    user, denied = admin_user(request)\n    if denied:\n        return denied\n    try:\n        admin_service.remove(qid)\n    except AdminError as e:\n        return render_admin(request, e.status, error=e.message)\n    log.info("管理员 %s 删除了第 %d 题", user["username"], qid)\n    return render_admin(request, message=f"已删除第 {qid} 题")\n\n# main.py 的 login_form：注册那一行改成\nadmin_service.on_register(auth.register(username.strip(), password))\n\n<!-- templates/admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  {% if message %}<p>{{ message }}</p>{% endif %}\n  {% if error %}<p style="color: red">{{ error }}</p>{% endif %}\n  {% if is_admin %}\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  {% endif %}\n</body>\n</html>',explain:[{at:'# main.py：管理页面',to:'}, status_code=status)',text:'统一渲染管理页面：状态码、提示、错误。403 说明不是管理员，不显示表单。'},{at:'def admin_user(request):',to:'return None, RedirectResponse("/login", status_code=303)',text:'先用第 10 关的 page_user 认人，没登录时准备一个跳到登录页的响应。'},{at:'try:',to:'return user, None',text:'再看角色：不是管理员时准备一个 403 页面。Python 函数可以一次返回两个值（元组），调用方用 user, denied = … 分别接住。'},{at:'@app.get("/admin", response_class=HTMLResponse)',to:'return render_admin(request)',text:'打开管理页面：不通过就返回准备好的响应，通过了显示空表单。'},{at:'@app.post("/admin/questions", response_class=HTMLResponse)',to:'return denied',text:'表单的四个字段用 Form 取出；先检查管理员。'},{at:'try:',to:'return render_admin(request, message=f"已新增第 {q[\'id\']} 题")',text:'检查并保存，不合格时显示 400；成功后记审计日志，显示新题的编号。'},{at:'@app.post("/admin/questions/delete", response_class=HTMLResponse)',to:'return denied',text:'表单字段叫 id，和 Python 自带的 id 函数重名，所以参数叫 qid，用 alias="id" 对上表单的名字。'},{at:'try:',to:'return render_admin(request, message=f"已删除第 {qid} 题")',text:'删除，没有这道题时显示 404。'},{at:'# main.py 的 login_form',to:'admin_service.on_register(auth.register(',text:'页面上注册成功后也调用 on_register，名单里的用户名才会成为管理员。'},{at:'<!-- templates/admin.html -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'{% endif %}',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}]}},'template-java':{body:'模板渲染的做法：新增管理页面 /admin，上面两个表单：新增题目提交到 POST /admin/questions，删除题目提交到 POST /admin/questions/delete。后端调用和 JSON 接口同一个管理服务，再渲染同一个页面，把结果（“已新增第 n 题”）或错误提示显示出来。\n没登录时重定向到登录页；登录了但不是管理员，返回 403，页面上只显示“需要管理员权限”。\n还有一处要补：登录页的“注册”也要调用 OnRegister，否则用名单里的用户名在页面上注册，不会成为管理员。',practice:{steps:['新建 controller/AdminPageController.java（代码第一部分），补完 TODO；按中间的注释修改 LoginPageController.java。','新建 src/main/resources/templates/admin.html（代码最后一部分），首页加一个“管理题库”链接指向 /admin。','用 ADMIN_USERNAMES 里的账号登录，打开 /admin 新增一道题，到题库里找到它，再按编号删掉。换一个普通账号打开 /admin，应该看到“需要管理员权限”。'],expect:'管理题库\n已新增第 25 题\n新增题目  科目 [go] 难度 [1▾]  题目 [……]  参考答案 [……]  [新增]\n删除题目  题目编号 [  ]  [删除]'},code:'// controller/AdminPageController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.service.AdminService;\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.StudyService;\nimport jakarta.servlet.http.HttpServletResponse;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.*;\n\n@Controller\npublic class AdminPageController {\n\n    private static final Logger log = LoggerFactory.getLogger(AdminPageController.class);\n\n    private final AuthService auth;\n    private final AdminService admin;\n\n    public AdminPageController(AuthService auth, AdminService admin) {\n        this.auth = auth;\n        this.admin = admin;\n    }\n\n    // 页面版的“先认人”：没登录时返回 null\n    private User pageUser(String token) {\n        try {\n            return auth.currentUser(token);\n        } catch (AuthService.AuthException e) {\n            return null;\n        }\n    }\n\n    // 渲染管理页面：403 时不显示表单\n    private String show(Model model, HttpServletResponse response, int status, String message, String error) {\n        response.setStatus(status);\n        model.addAttribute("isAdmin", status != 403);\n        model.addAttribute("message", message);\n        model.addAttribute("error", error);\n        return "admin";\n    }\n\n    @GetMapping("/admin")\n    public String page(@CookieValue(name = "session", required = false) String token,\n                       Model model, HttpServletResponse response) {\n        User user = pageUser(token);\n        if (user == null) {\n            return "redirect:/login";\n        }\n        try {\n            admin.requireAdmin(user);\n            return show(model, response, 200, "", "");\n        } catch (StudyService.StudyException e) {\n            return show(model, response, e.status, "", e.getMessage());\n        }\n    }\n\n    @PostMapping("/admin/questions")\n    public String create(@CookieValue(name = "session", required = false) String token,\n                         @RequestParam(defaultValue = "") String category, @RequestParam(defaultValue = "") String title,\n                         @RequestParam(defaultValue = "") String answer, @RequestParam(defaultValue = "0") int difficulty,\n                         Model model, HttpServletResponse response) {\n        // TODO 1：和 page 方法一样先认人、requireAdmin；然后 admin.create(admin.clean(0, …))，记一行日志，\n        //         show(…, 200, "已新增第 n 题", "")；接住 StudyService.StudyException 时 show(…, e.status, "", e.getMessage())\n        return "admin";\n    }\n\n    @PostMapping("/admin/questions/delete")\n    public String delete(@CookieValue(name = "session", required = false) String token,\n                         @RequestParam(defaultValue = "0") int id, Model model, HttpServletResponse response) {\n        // TODO 2：同样先检查，再 admin.delete(id)；成功显示“已删除第 n 题”，出错的处理和上面一样\n        return "admin";\n    }\n}\n\n// controller/LoginPageController.java：注入 AdminService（加字段和构造函数参数），注册那一行改成\nadmin.onRegister(auth.register(username.strip(), password));\n\n<!-- templates/admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN" xmlns:th="http://www.thymeleaf.org">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  <p th:if="${!message.isEmpty()}" th:text="${message}">提示</p>\n  <p th:if="${!error.isEmpty()}" th:text="${error}" style="color: red">错误</p>\n  <th:block th:if="${isAdmin}">\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  </th:block>\n</body>\n</html>',explain:[{at:'// controller/AdminPageController.java',to:'import org.springframework.web.bind.annotation.*;',text:'管理页面的控制器，放在一个新类里。'},{at:'@Controller',to:'this.admin = admin;',text:'@Controller 返回的是模板名，不是 JSON。注入认证服务和管理服务，log 用来记审计日志。'},{at:'// 页面版的“先认人”',to:'return null;',text:'和第 10 关的页面控制器一样：没登录时返回 null。'},{at:'// 渲染管理页面',to:'return "admin";',text:'统一渲染管理页面：设置状态码，把提示和错误放进模型。403 说明不是管理员，不显示表单。'},{at:'@GetMapping("/admin")',to:'return "redirect:/login";',text:'打开管理页面：没登录跳到登录页。'},{at:'try {',to:'return show(model, response, e.status, "", e.getMessage());',text:'不是管理员时 requireAdmin 抛出 403 的业务异常，这里接住，渲染 403 页面；是管理员就显示空表单。'},{at:'@PostMapping("/admin/questions")',to:'return "admin";',text:'提交新增表单，要你补全。@RequestParam 从表单里按名字取值，难度直接声明成 int，Spring 会转换。'},{at:'@PostMapping("/admin/questions/delete")',to:'return "admin";',text:'提交删除表单，要你补全。'},{at:'// controller/LoginPageController.java',to:'admin.onRegister(auth.register(',text:'页面上注册成功后也调用 onRegister，名单里的用户名才会成为管理员。'},{at:'<!-- templates/admin.html -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'</th:block>',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}],solution:{code:'// controller/AdminPageController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.model.Question;\nimport com.example.zixishi.model.User;\nimport com.example.zixishi.service.AdminService;\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.StudyService;\nimport jakarta.servlet.http.HttpServletResponse;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.stereotype.Controller;\nimport org.springframework.ui.Model;\nimport org.springframework.web.bind.annotation.*;\n\n@Controller\npublic class AdminPageController {\n\n    private static final Logger log = LoggerFactory.getLogger(AdminPageController.class);\n\n    private final AuthService auth;\n    private final AdminService admin;\n\n    public AdminPageController(AuthService auth, AdminService admin) {\n        this.auth = auth;\n        this.admin = admin;\n    }\n\n    // 页面版的“先认人”：没登录时返回 null\n    private User pageUser(String token) {\n        try {\n            return auth.currentUser(token);\n        } catch (AuthService.AuthException e) {\n            return null;\n        }\n    }\n\n    // 渲染管理页面：403 时不显示表单\n    private String show(Model model, HttpServletResponse response, int status, String message, String error) {\n        response.setStatus(status);\n        model.addAttribute("isAdmin", status != 403);\n        model.addAttribute("message", message);\n        model.addAttribute("error", error);\n        return "admin";\n    }\n\n    @GetMapping("/admin")\n    public String page(@CookieValue(name = "session", required = false) String token,\n                       Model model, HttpServletResponse response) {\n        User user = pageUser(token);\n        if (user == null) {\n            return "redirect:/login";\n        }\n        try {\n            admin.requireAdmin(user);\n            return show(model, response, 200, "", "");\n        } catch (StudyService.StudyException e) {\n            return show(model, response, e.status, "", e.getMessage());\n        }\n    }\n\n    @PostMapping("/admin/questions")\n    public String create(@CookieValue(name = "session", required = false) String token,\n                         @RequestParam(defaultValue = "") String category, @RequestParam(defaultValue = "") String title,\n                         @RequestParam(defaultValue = "") String answer, @RequestParam(defaultValue = "0") int difficulty,\n                         Model model, HttpServletResponse response) {\n        User user = pageUser(token);\n        if (user == null) {\n            return "redirect:/login";\n        }\n        try {\n            admin.requireAdmin(user);\n            Question q = admin.create(admin.clean(0, category, title, answer, difficulty));\n            log.info("管理员 {} 新增了第 {} 题", user.username(), q.id());\n            return show(model, response, 200, "已新增第 " + q.id() + " 题", "");\n        } catch (StudyService.StudyException e) {\n            return show(model, response, e.status, "", e.getMessage());\n        }\n    }\n\n    @PostMapping("/admin/questions/delete")\n    public String delete(@CookieValue(name = "session", required = false) String token,\n                         @RequestParam(defaultValue = "0") int id, Model model, HttpServletResponse response) {\n        User user = pageUser(token);\n        if (user == null) {\n            return "redirect:/login";\n        }\n        try {\n            admin.requireAdmin(user);\n            admin.delete(id);\n            log.info("管理员 {} 删除了第 {} 题", user.username(), id);\n            return show(model, response, 200, "已删除第 " + id + " 题", "");\n        } catch (StudyService.StudyException e) {\n            return show(model, response, e.status, "", e.getMessage());\n        }\n    }\n}\n\n// controller/LoginPageController.java：注入 AdminService（加字段和构造函数参数），注册那一行改成\nadmin.onRegister(auth.register(username.strip(), password));\n\n<!-- templates/admin.html -->\n<!DOCTYPE html>\n<html lang="zh-CN" xmlns:th="http://www.thymeleaf.org">\n<head>\n  <meta charset="utf-8">\n  <title>管理题库 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>管理题库</h1>\n  <p th:if="${!message.isEmpty()}" th:text="${message}">提示</p>\n  <p th:if="${!error.isEmpty()}" th:text="${error}" style="color: red">错误</p>\n  <th:block th:if="${isAdmin}">\n  <h2>新增题目</h2>\n  <form method="post" action="/admin/questions">\n    <p>\n      <label>科目 <input name="category" placeholder="go" required></label>\n      <label>难度 <select name="difficulty"><option>1</option><option>2</option><option>3</option></select></label>\n    </p>\n    <p><label>题目<br><input name="title" size="60" maxlength="200" required></label></p>\n    <p><label>参考答案<br><textarea name="answer" rows="6" cols="60" maxlength="2000" required></textarea></label></p>\n    <button>新增</button>\n  </form>\n  <h2>删除题目</h2>\n  <form method="post" action="/admin/questions/delete">\n    <label>题目编号 <input name="id" type="number" min="1" required></label>\n    <button>删除</button>\n  </form>\n  </th:block>\n</body>\n</html>',explain:[{at:'// controller/AdminPageController.java',to:'import org.springframework.web.bind.annotation.*;',text:'管理页面的控制器，放在一个新类里。'},{at:'@Controller',to:'this.admin = admin;',text:'@Controller 返回的是模板名，不是 JSON。注入认证服务和管理服务，log 用来记审计日志。'},{at:'// 页面版的“先认人”',to:'return null;',text:'和第 10 关的页面控制器一样：没登录时返回 null。'},{at:'// 渲染管理页面',to:'return "admin";',text:'统一渲染管理页面：设置状态码，把提示和错误放进模型。403 说明不是管理员，不显示表单。'},{at:'@GetMapping("/admin")',to:'return "redirect:/login";',text:'打开管理页面：没登录跳到登录页。'},{at:'try {',to:'return show(model, response, e.status, "", e.getMessage());',text:'不是管理员时 requireAdmin 抛出 403 的业务异常，这里接住，渲染 403 页面；是管理员就显示空表单。'},{at:'@PostMapping("/admin/questions")',to:'return "redirect:/login";',text:'@RequestParam 从表单里按名字取值，难度直接声明成 int。先认人。'},{at:'try {',to:'return show(model, response, e.status, "", e.getMessage());',text:'再看角色；检查合格后保存，记审计日志，显示新题的编号。不是管理员（403）或题目不合格（400）都由同一个 catch 显示出来。'},{at:'@PostMapping("/admin/questions/delete")',to:'return "redirect:/login";',text:'删除表单只有一个编号。'},{at:'try {',to:'return show(model, response, e.status, "", e.getMessage());',text:'检查管理员后删除，没有这道题时显示 404。'},{at:'// controller/LoginPageController.java',to:'admin.onRegister(auth.register(',text:'页面上注册成功后也调用 onRegister，名单里的用户名才会成为管理员。'},{at:'<!-- templates/admin.html -->',to:'</head>',text:'管理页面的模板。'},{at:'<body>',to:'<h1>管理题库</h1>',text:'返回链接和标题。'},{at:'<h1>管理题库</h1>',to:'<h2>新增题目</h2>',text:'有结果就显示结果，有错误就用红字显示错误。只有管理员才显示下面的两个表单（不是管理员时只看到“需要管理员权限”）。'},{at:'<form method="post" action="/admin/questions">',to:'</form>',text:'新增题目的表单：控件的 name 和 JSON 接口的字段名一样。难度是下拉框，选项的值就是文字 1、2、3。'},{at:'<h2>删除题目</h2>',to:'</form>',text:'删除题目的表单：只填一个编号。'},{at:'</th:block>',text:'只给管理员看的部分到这里结束。'},{at:'</body>',to:'</html>',text:'页面结束。'}]}}}},
  {title:'验收：管理接口和权限',body:'验收脚本用两个账号：一个普通用户，一个名叫 admin_check 的管理员。所以启动后端前要设置环境变量 ADMIN_USERNAMES=admin_check。\n脚本会检查：没登录 401、普通用户 403；管理员能新增、修改、删除题目，改动马上反映在公开的题目接口和科目统计里；不合格的输入 400、不存在的题目 404。脚本新增的题目最后会被它自己删掉，不会留在你的题库里。',practice:{steps:['停掉后端，设置环境变量 ADMIN_USERNAMES=admin_check 再启动。','把下面的脚本保存为 checks/check_l16.py，运行 python checks/check_l16.py，直到全部 ✓。','用你自己的用户名试试：把它加进 ADMIN_USERNAMES（逗号隔开）重启，登录后打开管理页面加一道题。','全部通过后提交：git add . 然后 git commit -m "第 16 关：管理后台和权限"。'],expect:'✓ 健康检查仍然正常\n✓ 没登录时管理接口返回 401\n✓ 普通用户访问管理接口返回 403\n✓ 管理员新增题目返回 201，公开接口能查到\n✓ 不合格的题目返回 400\n✓ 修改题目生效，修改不存在的题目返回 404\n✓ 新题出现在科目统计里\n✓ 删除题目返回 204，之后查不到了\n\n通过 8 / 8'},code:`import http.cookiejar
import json
import random
import sys
import urllib.error
import urllib.request

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
passed = 0


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def client(username=None):
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))

    def call(method, path, body=None):
        data = json.dumps(body).encode("utf-8") if body is not None else None
        req = urllib.request.Request(BASE + path, data=data, method=method, headers={"Content-Type": "application/json"})
        try:
            with opener.open(req, timeout=10) as r:
                status, raw = r.status, r.read()
        except urllib.error.HTTPError as e:
            status, raw = e.code, e.read()
        except OSError as e:
            sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")
        try:
            return status, json.loads(raw.decode("utf-8") or "null")
        except ValueError:
            return status, None

    if username:
        user = {"username": username, "password": "password123"}
        call("POST", "/api/register", user)
        call("POST", "/api/login", user)
    return call


def categories(call):
    return {c["category"]: c["count"] for c in call("GET", "/api/categories")[1]}


new = {"category": "check", "title": "验收脚本新增的题目", "answer": "这是参考答案。", "difficulty": 2}

guest = client()
status, data = guest("GET", "/api/health")
check("健康检查仍然正常", status == 200 and data == {"status": "ok"})
check("没登录时管理接口返回 401", guest("POST", "/api/admin/questions", new)[0] == 401)

user = client(f"u_{random.randint(100000, 999999)}")
check("普通用户访问管理接口返回 403", user("POST", "/api/admin/questions", new)[0] == 403
      and user("DELETE", "/api/admin/questions/1")[0] == 403)

admin = client("admin_check")
status, created = admin("POST", "/api/admin/questions", new)
qid = created.get("id") if isinstance(created, dict) else None
_, fetched = guest("GET", f"/api/questions/{qid}")
check("管理员新增题目返回 201，公开接口能查到", status == 201 and isinstance(qid, int)
      and isinstance(fetched, dict) and fetched.get("title") == new["title"])
bad = [admin("POST", "/api/admin/questions", {**new, **change})[0]
       for change in ({"difficulty": 5}, {"title": "  "}, {"category": "Bad Name!"})]
check("不合格的题目返回 400", bad == [400, 400, 400])

status, _ = admin("PUT", f"/api/admin/questions/{qid}", {**new, "title": "改过的题目"})
_, fetched = guest("GET", f"/api/questions/{qid}")
check("修改题目生效，修改不存在的题目返回 404", status == 200 and isinstance(fetched, dict)
      and fetched.get("title") == "改过的题目" and admin("PUT", "/api/admin/questions/99999", new)[0] == 404)
check("新题出现在科目统计里", categories(guest).get("check") == 1)

status, _ = admin("DELETE", f"/api/admin/questions/{qid}")
check("删除题目返回 204，之后查不到了", status == 204 and guest("GET", f"/api/questions/{qid}")[0] == 404
      and admin("DELETE", f"/api/admin/questions/{qid}")[0] == 404 and "check" not in categories(guest))

print(f"\\n通过 {passed} / 8")`,explain:[{at:'import http.cookiejar',to:'import urllib.request',text:'和前几关一样的工具。'},{at:'BASE = sys.argv[1]',to:'passed = 0',text:'服务地址和通过数。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'检查一项并打印结果。'},{at:'def client(username=None):',to:'return call',text:'创建一个“客户端”：有自己的 Cookie 罐子；传了用户名就先注册（已经注册过会返回 409，没关系）再登录。'},{at:'def categories(call):',to:'return {c["category"]: c["count"] for c in call("GET", "/api/categories")[1]}',text:'把科目统计变成“科目 → 题数”的字典。'},{at:'new = {',text:'要新增的题目，科目叫 check，正常的题库里没有它。'},{at:'guest = client()',to:'check("没登录时管理接口返回 401"',text:'没登录的访客：健康检查，管理接口返回 401。'},{at:'user = client(f"u_',to:'and user("DELETE", "/api/admin/questions/1")[0] == 403)',text:'普通用户：已经登录了，但没有权限，返回 403。'},{at:'admin = client("admin_check")',to:'and isinstance(fetched, dict) and fetched.get("title") == new["title"])',text:'管理员新增题目：返回 201 和新题目（带自动生成的编号），公开的详情接口马上能查到。'},{at:'bad = [',to:'check("不合格的题目返回 400"',text:'三种不合格的输入：难度超出范围、题目只有空格、科目名不合规。{**new, **change} 在原来的题目上改一个字段。'},{at:'status, _ = admin("PUT"',to:'and fetched.get("title") == "改过的题目" and admin("PUT", "/api/admin/questions/99999", new)[0] == 404)',text:'修改题目，公开接口看到新标题；修改不存在的题目返回 404。'},{at:'check("新题出现在科目统计里"',text:'科目统计是从题目表算出来的，新科目自动出现。'},{at:'status, _ = admin("DELETE"',to:'and admin("DELETE", f"/api/admin/questions/{qid}")[0] == 404 and "check" not in categories(guest))',text:'删除返回 204，之后详情 404，再删一次也是 404，科目统计里也没有了。'},{at:'print(f"\\n通过 {passed} / 8")',text:'打印总的通过数。'}]},
  {title:'这一关学到了什么',body:'一、认证是“你是谁”（401），授权是“你能做什么”（403），先认人再看角色；\n二、RBAC：用户有角色，规则写在一个“要求管理员”的地方，所有管理接口都经过它；\n三、数据库迁移：给已有的表加列要先检查，保证重复启动也不出错；\n四、管理接口照样要严格校验输入，修改和删除不存在的数据返回 404，用“影响了几行”来判断；\n五、管理操作记审计日志：谁、什么时候、做了什么。\n下一关给项目加上自动化测试，让每次修改都能快速确认没有改坏。'}
 ],quiz:[
 {id:'pj-admin-1',q:'用户已经登录，但不是管理员，访问管理接口应该返回？',options:['403 Forbidden','401 Unauthorized','404 Not Found','400 Bad Request'],why:['','401 表示没有登录（未认证），他已经登录了。','接口是存在的，只是他没有权限。','请求本身没有格式问题。'],answer:0,explain:'认证（你是谁）没通过是 401；认证通过了但没有权限（授权没通过）是 403。'},
 {id:'pj-admin-2',q:'管理接口检查身份的顺序应该是？',options:['先确认登录，再看是不是管理员','先看是不是管理员，再确认登录','两项检查同时做，顺序无所谓','只看角色，不用确认是否登录'],why:['','还不知道是谁，就没法查他的角色。','顺序会影响返回 401 还是 403，有所谓。','角色是属于某个用户的，必须先知道是谁。'],answer:0,explain:'先认人（没登录 401），再看角色（不是管理员 403）。'},
 {id:'pj-admin-3',type:'judge',q:'SQLite 的 ALTER TABLE … ADD COLUMN 没有 IF NOT EXISTS，所以加列之前要先检查这一列是否已经存在。',answer:true,explain:'正确。否则第二次启动时会因为“列已经存在”报错。我们用 pragma_table_info 查出表的所有列再判断。'},
 {id:'pj-admin-4',q:'给已有数据的 users 表加上 role 列并设置 DEFAULT \'user\'，已有的那些用户会怎样？',options:['角色都变成默认值 user','角色都是空值，要手动补','这些用户会被删除重建','加列操作会直接报错'],why:['','只有没写 DEFAULT 时才是空值（而且 NOT NULL 不允许）。','加列不会动已有的行。','有默认值时加 NOT NULL 列是允许的。'],answer:0,explain:'ADD COLUMN 带 DEFAULT 时，已有的每一行都得到默认值，所以 NOT NULL 也能加上。'},
 {id:'pj-admin-5',q:'修改题目时，怎么知道这道题存不存在？',options:['看 UPDATE 影响了几行','先查出全部题目再比较','看数据库有没有报错','比较修改前后的题目数量'],why:['','把全部题目查出来太浪费。','编号不存在时 UPDATE 不会报错，只是一行也没改。','修改不会改变题目数量。'],answer:0,explain:'UPDATE 和 DELETE 都会返回受影响的行数，0 行说明没有这道题，返回 404。'},
 {id:'pj-admin-6',type:'multi',q:'下面哪些输入，管理接口应该返回 400？（多选）',options:['难度是 5','题目只有几个空格','科目名是 Bad Name!','科目名是 go-basic'],why:['','','','go-basic 只有小写字母和横线，是合法的。'],answers:[0,1,2],explain:'难度只能是 1–3；题目去掉首尾空格后是空的；科目名只能用小写字母、数字和横线。'},
 {id:'pj-admin-7',type:'judge',q:'只有管理员能调用管理接口，所以管理接口可以不检查输入。',answer:false,explain:'错误。管理员也会手滑，账号也可能被盗。所有接口的输入都要检查。'},
 {id:'pj-admin-8',type:'fill',q:'“按角色决定一个用户能做什么”的访问控制方式，英文缩写是 ＿。',accepted:['RBAC'],explain:'RBAC（Role-Based Access Control，基于角色的访问控制）。'},
 {id:'pj-admin-9',q:'删除成功返回 204，和 200 的区别是？',options:['204 表示成功但没有正文','204 表示请求还在处理中','204 表示需要客户端重试','204 表示删除了多条数据'],why:['','“处理中”是 202 Accepted。','重试和状态码 204 无关。','状态码不表示删了几条。'],answer:0,explain:'204 No Content：成功了，但没有内容要返回。前端收到 204 时不能去解析 JSON 正文。'},
 {id:'pj-admin-10',type:'short',q:'管理员名单由环境变量 ADMIN_USERNAMES 指定。请说明：一个名单里的用户名，在“启动前已经注册”和“启动后才注册”两种情况下，分别是怎样成为管理员的？',reference:'启动前已经注册：服务启动时执行迁移，把名单里已经存在的用户名的 role 设成 admin。启动后才注册：注册成功后调用 OnRegister，发现用户名在名单里，就把他设成 admin（页面上的注册也要调用）。',points:['启动时把名单里已注册的账号设成 admin','注册成功后检查名单并设成 admin','页面注册和接口注册都要处理'],explain:'两个时机都要处理，否则总有一种情况漏掉。'},
 {id:'pj-admin-go-1',stack:'go',q:'Go 中 res.RowsAffected() 返回 0 时，UpdateQuestion 应该返回？',options:['返回 ErrNotFound','返回 nil 表示成功','返回一个空的题目','直接 panic 退出'],why:['','一行都没改，不能当成功。','函数只返回错误，不返回题目。','这是正常的业务情况，不该让程序崩溃。'],answer:0,explain:'没有这一行就返回 ErrNotFound，处理请求的层用 errors.Is 认出来，返回 404。'},
 {id:'pj-admin-java-1',stack:'java',q:'Java 中 SQLite 的 last_insert_rowid() 为什么要和 INSERT 放在同一个 @Transactional 方法里？',options:['它只返回同一连接上次插入的编号','它必须在事务中执行，否则报错','这样插入的速度会快很多','事务能让编号从 1 开始计数'],why:['','在事务外也能执行，只是可能拿到别的连接的结果。','速度不是原因。','事务和编号从几开始无关。'],answer:0,explain:'last_insert_rowid() 是“这个连接上一次插入的编号”。放在同一个事务里，两条语句用的是同一个连接。'},
 {id:'pj-admin-node-1',stack:'node',q:'Node.js 中 better-sqlite3 的 run() 返回的对象里，哪个字段表示改了几行？',options:['changes','lastInsertRowid','rowCount','affected'],why:['','它是新插入行的编号。','这是其他数据库库的命名。','没有这个字段。'],answer:0,explain:'result.changes 是受影响的行数，result.lastInsertRowid 是新插入行的编号。'},
 {id:'pj-admin-python-1',stack:'python',q:'Python 的 sqlite3 中，执行 UPDATE 之后，cursor 的哪个属性表示改了几行？',options:['rowcount','lastrowid','total_changes','changes'],why:['','它是最后插入行的编号。','这是连接对象的属性，统计的是连接打开以来的总数。','没有这个属性。'],answer:0,explain:'cur.rowcount 是这条语句影响的行数，大于 0 说明题目存在。'}]};
